import React, { useState, useEffect, useRef } from 'react';
import {
  Box,
  Container,
  Typography,
  Card,
  CardContent,
  Button,
  TextField,
  Grid,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Chip,
  IconButton,
  Paper,
  CircularProgress,
  Alert,
  Tab,
  Tabs,
  Menu,
  MenuItem,
  Badge,
} from '@mui/material';
import {
  Add as AddIcon,
  Send as SendIcon,
  Close as CloseIcon,
  SupportAgent as SupportIcon,
  MoreVert as MoreVertIcon,
} from '@mui/icons-material';
import { useCustomerAuth } from '../contexts/CustomerAuthContext';
import { useNavigate } from 'react-router-dom';
import { formatDistanceToNow, format } from 'date-fns';
import toast from 'react-hot-toast';

const API_URL = 'https://godelivo.com';

const CustomerSupport = () => {
  const [tickets, setTickets] = useState([]);
  const [selectedTicket, setSelectedTicket] = useState(null);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [createDialog, setCreateDialog] = useState(false);
  const [newTicket, setNewTicket] = useState({
    category: 'Technical',
    subject: '',
    description: ''
  });
  const [activeTab, setActiveTab] = useState(0);
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedTicketForMenu, setSelectedTicketForMenu] = useState(null);
  const [socketConnected, setSocketConnected] = useState(false);
  const [typingUsers, setTypingUsers] = useState({});
  
  const messagesEndRef = useRef(null);
  const typingTimeoutRef = useRef(null);
  const { customer, token, socket, logout } = useCustomerAuth();
  const navigate = useNavigate();

  // Socket connection status
  useEffect(() => {
    if (!socket) return;

    const handleConnect = () => {
      console.log('✅ Socket connected successfully');
      setSocketConnected(true);
      
      // Rejoin ticket room if viewing one
      if (selectedTicket?._id) {
        socket.emit('join-ticket', selectedTicket._id);
      }
    };

    const handleDisconnect = (reason) => {
      console.log('❌ Socket disconnected:', reason);
      setSocketConnected(false);
    };

    const handleConnectError = (error) => {
      console.error('⚠️ Socket connection error:', error);
      setSocketConnected(false);
    };

    const handleReconnect = (attemptNumber) => {
      console.log(`🔄 Socket reconnected after ${attemptNumber} attempts`);
      setSocketConnected(true);
      
      // Rejoin ticket room if viewing one
      if (selectedTicket?._id) {
        socket.emit('join-ticket', selectedTicket._id);
      }
    };

    socket.on('connect', handleConnect);
    socket.on('disconnect', handleDisconnect);
    socket.on('connect_error', handleConnectError);
    socket.on('reconnect', handleReconnect);

    return () => {
      socket.off('connect', handleConnect);
      socket.off('disconnect', handleDisconnect);
      socket.off('connect_error', handleConnectError);
      socket.off('reconnect', handleReconnect);
    };
  }, [socket, selectedTicket]);

  // Socket event listeners
  useEffect(() => {
    if (!socket) return;

    const handleNewMessage = (data) => {
      console.log('📨 New message received via socket:', data);
      
      toast.success('New message received');
      
      // Update tickets list to show new message indicator
      setTickets(prevTickets => 
        prevTickets.map(ticket => 
          ticket._id === data.ticketId 
            ? { ...ticket, hasNewMessage: true }
            : ticket
        )
      );

      // Update the selected ticket if it's the current one
      if (selectedTicket && data.ticketId === selectedTicket._id) {
        setSelectedTicket(prev => {
          const messageExists = prev.messages?.some(m => m._id === data.message._id);
          if (!messageExists) {
            return {
              ...prev,
              messages: [...(prev.messages || []), data.message],
              hasNewMessage: false
            };
          }
          return prev;
        });
        
        setTimeout(() => {
          scrollToBottom();
        }, 100);
      }
    };

    const handleTicketUpdated = (data) => {
      console.log('🔄 Ticket updated via socket:', data);
      
      if (selectedTicket && data.ticketId === selectedTicket._id) {
        setSelectedTicket(prev => ({
          ...prev,
          status: data.status
        }));
        toast.info(`Ticket status updated to ${data.status}`);
      }
      
      // Update tickets list
      setTickets(prevTickets => 
        prevTickets.map(ticket => 
          ticket._id === data.ticketId 
            ? { ...ticket, status: data.status }
            : ticket
        )
      );
    };

    const handleUserTyping = ({ userId, userName }) => {
      setTypingUsers(prev => ({ ...prev, [userId]: userName }));
      setTimeout(() => {
        setTypingUsers(prev => {
          const newState = { ...prev };
          delete newState[userId];
          return newState;
        });
      }, 3000);
    };

    socket.on('new-message', handleNewMessage);
    socket.on('ticket-updated', handleTicketUpdated);
    socket.on('user-typing', handleUserTyping);

    return () => {
      socket.off('new-message', handleNewMessage);
      socket.off('ticket-updated', handleTicketUpdated);
      socket.off('user-typing', handleUserTyping);
    };
  }, [socket, selectedTicket]);

  useEffect(() => {
    if (customer?.id) {
      fetchTickets();
    }
  }, [customer]);

  useEffect(() => {
    scrollToBottom();
  }, [selectedTicket?.messages]);

  // Join ticket room when selected ticket changes
  useEffect(() => {
    if (selectedTicket?._id && socketConnected && socket) {
      socket.emit('join-ticket', selectedTicket._id);
      console.log('🎯 Joined ticket room:', selectedTicket._id);
    }

    return () => {
      if (selectedTicket?._id && socketConnected && socket) {
        socket.emit('leave-ticket', selectedTicket._id);
        console.log('👋 Left ticket room:', selectedTicket._id);
      }
    };
  }, [selectedTicket, socketConnected]);

  // Auto-refresh tickets periodically
  useEffect(() => {
    const interval = setInterval(() => {
      if (!selectedTicket) {
        fetchTickets();
      }
    }, 30000); // Refresh every 30 seconds

    return () => clearInterval(interval);
  }, [selectedTicket]);

  const fetchTickets = async () => {
    if (!customer?.id || !token) {
      console.log('No customer ID or token:', { customer, token });
      return;
    }
    
    setLoading(true);
    try {
      console.log('Fetching tickets for customer:', customer.id);
      const response = await fetch(`${API_URL}/api/support/user/${customer.id}/CUSTOMER`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const data = await response.json();
      console.log('Tickets response:', data);
      
      if (data.success) {
        setTickets(data.data);
      } else {
        toast.error(data.message || 'Failed to fetch tickets');
      }
    } catch (error) {
      console.error('Fetch tickets error:', error);
      toast.error('Failed to fetch tickets');
    } finally {
      setLoading(false);
    }
  };

  const fetchTicket = async (ticketId) => {
    try {
      const response = await fetch(`${API_URL}/api/support/tickets/${ticketId}`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const data = await response.json();
      console.log('Ticket details:', data);
      
      if (data.success) {
        setSelectedTicket(data.data);
        // Clear new message indicator
        setTickets(prevTickets => 
          prevTickets.map(t => 
            t._id === ticketId 
              ? { ...t, hasNewMessage: false }
              : t
          )
        );
      } else {
        toast.error(data.message || 'Failed to load ticket details');
      }
    } catch (error) {
      console.error('Fetch ticket error:', error);
      toast.error('Failed to load ticket details');
    }
  };

  const handleCreateTicket = async () => {
    if (!newTicket.subject || !newTicket.description) {
      toast.error('Please fill all fields');
      return;
    }

    if (!customer?.id) {
      toast.error('Customer not found');
      return;
    }

    setLoading(true);
    try {
      const ticketData = {
        category: newTicket.category,
        subject: newTicket.subject,
        description: newTicket.description,
        reporterId: customer.id,
        reporterType: 'CUSTOMER'
      };

      const response = await fetch(`${API_URL}/api/support/tickets`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(ticketData)
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      if (data.success) {
        toast.success('Ticket created successfully');
        setCreateDialog(false);
        setNewTicket({ category: 'Technical', subject: '', description: '' });
        fetchTickets();
      } else {
        toast.error(data.message || 'Failed to create ticket');
      }
    } catch (error) {
      console.error('Error creating ticket:', error);
      toast.error('Network error');
    } finally {
      setLoading(false);
    }
  };

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !selectedTicket || !customer?.id) return;

    try {
      const messageData = {
        message: newMessage,
        userType: 'CUSTOMER',
        userId: customer.id
      };
      
      const response = await fetch(`${API_URL}/api/support/tickets/${selectedTicket._id}/messages`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(messageData)
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || `HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      if (data.success) {
        setNewMessage('');
        toast.success('Message sent');
      } else {
        toast.error(data.message || 'Failed to send message');
      }
    } catch (error) {
      console.error('Send message error:', error);
      toast.error(error.message || 'Network error');
    }
  };

  const handleViewTicket = (ticket) => {
    setSelectedTicket(ticket);
    fetchTicket(ticket._id);
  };

  const handleMenuOpen = (event, ticket) => {
    setAnchorEl(event.currentTarget);
    setSelectedTicketForMenu(ticket);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setSelectedTicketForMenu(null);
  };

  const handleTyping = () => {
    if (!selectedTicket || !socketConnected || !socket) return;

    socket.emit('typing', {
      ticketId: selectedTicket._id,
      userId: customer?.id,
      userName: customer?.name || 'Customer',
    });

    clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => {
      socket.emit('stop-typing', {
        ticketId: selectedTicket._id,
        userId: customer?.id,
      });
    }, 1000);
  };

  const scrollToBottom = () => {
    setTimeout(() => {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  const getStatusColor = (status) => {
    const colors = {
      'Open': 'error',
      'In Progress': 'warning',
      'Resolved': 'success',
      'Closed': 'default'
    };
    return colors[status] || 'default';
  };

  const getPriorityColor = (priority) => {
    const colors = {
      'Critical': 'error',
      'High': 'warning',
      'Medium': 'info',
      'Low': 'success'
    };
    return colors[priority] || 'default';
  };

  // Calculate stats from tickets
  const stats = {
    total: tickets.length,
    open: tickets.filter(t => t.status === 'Open').length,
    inProgress: tickets.filter(t => t.status === 'In Progress').length,
    resolved: tickets.filter(t => t.status === 'Resolved').length
  };

  const filteredTickets = tickets.filter(ticket => {
    if (activeTab === 0) return true;
    if (activeTab === 1) return ticket.status === 'Open';
    if (activeTab === 2) return ticket.status === 'In Progress';
    if (activeTab === 3) return ticket.status === 'Resolved';
    return true;
  });

  if (!customer) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: '#f5f5f5' }}>
      {/* Header */}
      <Box sx={{ bgcolor: '#FFB300', p: 2 }}>
        <Container maxWidth="lg">
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Box>
              <Typography variant="h5" sx={{ fontWeight: 700, color: '#000' }}>
                Support Center
              </Typography>
              <Typography variant="body2" sx={{ color: 'rgba(0,0,0,0.7)' }}>
                Welcome, {customer?.name || customer?.phone}
                {socketConnected ? (
                  <Chip
                    size="small"
                    label="Live"
                    color="success"
                    sx={{ ml: 1, height: 20, fontSize: '0.7rem' }}
                  />
                ) : (
                  <Chip
                    size="small"
                    label="Connecting..."
                    color="warning"
                    sx={{ ml: 1, height: 20, fontSize: '0.7rem' }}
                  />
                )}
              </Typography>
            </Box>
            <Button 
              variant="outlined" 
              onClick={logout}
              sx={{ borderColor: '#000', color: '#000' }}
            >
              Logout
            </Button>
          </Box>
        </Container>
      </Box>

      <Container maxWidth="lg" sx={{ py: 3 }}>
        {/* Stats Cards */}
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid item xs={6} sm={3}>
            <Card>
              <CardContent>
                <Typography variant="h4" sx={{ color: '#FFB300' }}>{stats.total}</Typography>
                <Typography variant="body2" color="text.secondary">Total Tickets</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={6} sm={3}>
            <Card>
              <CardContent>
                <Typography variant="h4" sx={{ color: '#f44336' }}>{stats.open}</Typography>
                <Typography variant="body2" color="text.secondary">Open</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={6} sm={3}>
            <Card>
              <CardContent>
                <Typography variant="h4" sx={{ color: '#ff9800' }}>{stats.inProgress}</Typography>
                <Typography variant="body2" color="text.secondary">In Progress</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={6} sm={3}>
            <Card>
              <CardContent>
                <Typography variant="h4" sx={{ color: '#4caf50' }}>{stats.resolved}</Typography>
                <Typography variant="body2" color="text.secondary">Resolved</Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        {/* Main Content */}
        <Grid container spacing={3}>
          {/* Left Column - Ticket List */}
          <Grid item xs={12} md={5}>
            <Card>
              <CardContent>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                  <Typography variant="h6">Your Tickets</Typography>
                  <Button
                    variant="contained"
                    startIcon={<AddIcon />}
                    onClick={() => setCreateDialog(true)}
                    sx={{ bgcolor: '#FFB300', color: '#000' }}
                  >
                    New Ticket
                  </Button>
                </Box>

                <Tabs
                  value={activeTab}
                  onChange={(e, v) => setActiveTab(v)}
                  sx={{ mb: 2, borderBottom: 1, borderColor: 'divider' }}
                >
                  <Tab label="All" />
                  <Tab label="Open" />
                  <Tab label="In Progress" />
                  <Tab label="Resolved" />
                </Tabs>

                {loading ? (
                  <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
                    <CircularProgress />
                  </Box>
                ) : filteredTickets.length === 0 ? (
                  <Alert severity="info">No tickets found</Alert>
                ) : (
                  filteredTickets.map((ticket) => (
                    <Card
                      key={ticket._id}
                      sx={{
                        mb: 1,
                        cursor: 'pointer',
                        bgcolor: selectedTicket?._id === ticket._id ? 'rgba(255, 179, 0, 0.1)' : 'transparent',
                        '&:hover': { bgcolor: 'rgba(255, 179, 0, 0.05)' },
                        position: 'relative'
                      }}
                      onClick={() => handleViewTicket(ticket)}
                    >
                      <CardContent sx={{ p: 2, '&:last-child': { pb: 2 } }}>
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                          <Box sx={{ flex: 1 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                              {ticket.hasNewMessage && (
                                <Badge color="error" variant="dot" />
                              )}
                              <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>
                                {ticket.ticketId} - {ticket.subject}
                              </Typography>
                            </Box>
                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 1 }}>
                              {ticket.description?.substring(0, 60)}...
                            </Typography>
                            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap' }}>
                              <Chip
                                label={ticket.status}
                                size="small"
                                color={getStatusColor(ticket.status)}
                                sx={{ height: 20, fontSize: '0.7rem' }}
                              />
                              <Chip
                                label={ticket.priority}
                                size="small"
                                color={getPriorityColor(ticket.priority)}
                                sx={{ height: 20, fontSize: '0.7rem' }}
                              />
                              <Typography variant="caption" color="text.secondary">
                                {ticket.createdAt ? formatDistanceToNow(new Date(ticket.createdAt), { addSuffix: true }) : ''}
                              </Typography>
                            </Box>
                          </Box>
                          <IconButton size="small" onClick={(e) => {
                            e.stopPropagation();
                            handleMenuOpen(e, ticket);
                          }}>
                            <MoreVertIcon fontSize="small" />
                          </IconButton>
                        </Box>
                      </CardContent>
                    </Card>
                  ))
                )}
              </CardContent>
            </Card>
          </Grid>

          {/* Right Column - Chat Window */}
          <Grid item xs={12} md={7}>
            <Card sx={{ height: '600px', display: 'flex', flexDirection: 'column' }}>
              {selectedTicket ? (
                <>
                  {/* Chat Header */}
                  <Box sx={{ p: 2, borderBottom: 1, borderColor: 'divider', bgcolor: '#f9f9f9' }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <Box>
                        <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
                          {selectedTicket.ticketId} - {selectedTicket.subject}
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 1, mt: 0.5, flexWrap: 'wrap' }}>
                          <Chip
                            label={selectedTicket.status}
                            size="small"
                            color={getStatusColor(selectedTicket.status)}
                          />
                          <Chip
                            label={selectedTicket.priority}
                            size="small"
                            color={getPriorityColor(selectedTicket.priority)}
                          />
                        </Box>
                      </Box>
                      <IconButton onClick={() => setSelectedTicket(null)}>
                        <CloseIcon />
                      </IconButton>
                    </Box>
                  </Box>

                  {/* Messages */}
                  <Box sx={{ flex: 1, overflow: 'auto', p: 2, bgcolor: '#f5f5f5' }}>
                    {selectedTicket.messages?.map((msg, index) => (
                      <Box
                        key={msg._id || index}
                        sx={{
                          display: 'flex',
                          justifyContent: msg.senderType === 'CUSTOMER' ? 'flex-end' : 'flex-start',
                          mb: 2
                        }}
                      >
                        <Paper
                          sx={{
                            maxWidth: '70%',
                            p: 1.5,
                            bgcolor: msg.senderType === 'CUSTOMER' ? '#FFB300' : 'white',
                            borderRadius: msg.senderType === 'CUSTOMER'
                              ? '16px 16px 4px 16px'
                              : '16px 16px 16px 4px'
                          }}
                        >
                          <Typography variant="caption" sx={{ display: 'block', fontWeight: 600 }}>
                            {msg.senderName}
                          </Typography>
                          <Typography variant="body2">{msg.message}</Typography>
                          <Typography variant="caption" sx={{ display: 'block', textAlign: 'right', mt: 0.5, opacity: 0.7 }}>
                            {msg.createdAt ? format(new Date(msg.createdAt), 'hh:mm a') : ''}
                          </Typography>
                        </Paper>
                      </Box>
                    ))}
                    {Object.keys(typingUsers).length > 0 && (
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, color: 'text.secondary' }}>
                        <CircularProgress size={12} />
                        <Typography variant="caption">
                          {Object.values(typingUsers).join(', ')} typing...
                        </Typography>
                      </Box>
                    )}
                    <div ref={messagesEndRef} />
                  </Box>

                  {/* Message Input */}
                  {selectedTicket.status !== 'Resolved' && selectedTicket.status !== 'Closed' && (
                    <Box sx={{ p: 2, borderTop: 1, borderColor: 'divider', bgcolor: 'white' }}>
                      <Box sx={{ display: 'flex', gap: 1 }}>
                        <TextField
                          fullWidth
                          size="small"
                          placeholder="Type your message..."
                          value={newMessage}
                          onChange={(e) => {
                            setNewMessage(e.target.value);
                            handleTyping();
                          }}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter' && !e.shiftKey) {
                              e.preventDefault();
                              handleSendMessage();
                            }
                          }}
                          multiline
                          maxRows={3}
                        />
                        <IconButton
                          color="primary"
                          onClick={handleSendMessage}
                          disabled={!newMessage.trim()}
                          sx={{ bgcolor: '#FFB300', color: '#000', '&:hover': { bgcolor: '#FFA000' } }}
                        >
                          <SendIcon />
                        </IconButton>
                      </Box>
                    </Box>
                  )}

                  {selectedTicket.status === 'Resolved' && (
                    <Alert severity="success" sx={{ m: 2 }}>
                      This ticket has been resolved. If you need further assistance, please create a new ticket.
                    </Alert>
                  )}
                </>
              ) : (
                <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100%' }}>
                  <SupportIcon sx={{ fontSize: 80, color: '#ccc', mb: 2 }} />
                  <Typography color="text.secondary">Select a ticket to view conversation</Typography>
                </Box>
              )}
            </Card>
          </Grid>
        </Grid>
      </Container>

      {/* Create Ticket Dialog */}
      <Dialog open={createDialog} onClose={() => setCreateDialog(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Create New Support Ticket</DialogTitle>
        <DialogContent>
          <TextField
            select
            fullWidth
            label="Category"
            value={newTicket.category}
            onChange={(e) => setNewTicket({ ...newTicket, category: e.target.value })}
            sx={{ mb: 2, mt: 1 }}
          >
            <MenuItem value="Payment">Payment Issue</MenuItem>
            <MenuItem value="Ride Issue">Ride Issue</MenuItem>
            <MenuItem value="Account">Account Issue</MenuItem>
            <MenuItem value="Technical">Technical Issue</MenuItem>
            <MenuItem value="Driver Complaint">Driver Complaint</MenuItem>
            <MenuItem value="Other">Other</MenuItem>
          </TextField>

          <TextField
            fullWidth
            label="Subject"
            value={newTicket.subject}
            onChange={(e) => setNewTicket({ ...newTicket, subject: e.target.value })}
            sx={{ mb: 2 }}
          />

          <TextField
            fullWidth
            label="Description"
            multiline
            rows={4}
            value={newTicket.description}
            onChange={(e) => setNewTicket({ ...newTicket, description: e.target.value })}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCreateDialog(false)}>Cancel</Button>
          <Button
            variant="contained"
            onClick={handleCreateTicket}
            disabled={loading}
            sx={{ bgcolor: '#FFB300', color: '#000', '&:hover': { bgcolor: '#FFA000' } }}
          >
            {loading ? <CircularProgress size={24} /> : 'Create Ticket'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Ticket Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
      >
        <MenuItem onClick={() => {
          if (selectedTicketForMenu) {
            handleViewTicket(selectedTicketForMenu);
          }
          handleMenuClose();
        }}>
          View Details
        </MenuItem>
      </Menu>
    </Box>
  );
};

export default CustomerSupport;