import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Avatar,
  Drawer,
  Grid,
  Tabs,
  Tab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogContentText,
  DialogActions,
  TextField,
  Modal,
  Fade,
  Backdrop,
  Tooltip,
  Alert,
  Pagination,
  CircularProgress,
  Divider,
  LinearProgress,
  Stack,
  Radio,
  RadioGroup,
  FormControlLabel,
  FormControl,
  FormLabel,
} from '@mui/material';
import {
  Visibility as ViewIcon,
  CheckCircle as VerifyIcon,
  Cancel as RejectIcon,
  Close as CloseIcon,
  Description as DocumentIcon,
  LocalShipping as VehicleIcon,
  AccountBalance as BankIcon,
  Person as PersonIcon,
  CalendarToday as CalendarIcon,
  Phone as PhoneIcon,
  Email as EmailIcon,
  LocationOn as LocationIcon,
  HourglassEmpty as PendingIcon,
  Assignment as ReviewIcon,
  VerifiedUser as VerifiedIcon,
  Block as RejectedIcon,
  Collections as GalleryIcon,
  Warning as WarningIcon,
  ZoomIn as ZoomInIcon,
  ZoomOut as ZoomOutIcon,
  CheckCircleOutline as PartiallyVerifiedIcon,
  ArrowBack as ArrowBackIcon,
  ArrowForward as ArrowForwardIcon,
  CreditCard as AadharIcon,
} from '@mui/icons-material';
import { toast } from 'react-hot-toast';
import axios from 'axios';

const API_BASE_URL = 'https://godelivo.com';

const statusConfig = {
  pending: { label: 'Pending', color: 'warning', icon: <PendingIcon /> },
  submitted: { label: 'Submitted', color: 'info', icon: <ReviewIcon /> },
  under_review: { label: 'Under Review', color: 'info', icon: <ReviewIcon /> },
  partially_verified: { label: 'Partially Verified', color: 'secondary', icon: <PartiallyVerifiedIcon /> },
  verified: { label: 'Verified', color: 'success', icon: <VerifiedIcon /> },
  rejected: { label: 'Rejected', color: 'error', icon: <RejectedIcon /> },
};

const documentStatusConfig = {
  pending: { label: 'Pending', color: 'warning', icon: <PendingIcon /> },
  verified: { label: 'Verified', color: 'success', icon: <VerifiedIcon /> },
  rejected: { label: 'Rejected', color: 'error', icon: <RejectedIcon /> },
};

const DriverVerification = () => {
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('all');
  const [selectedApp, setSelectedApp] = useState(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [lightboxImage, setLightboxImage] = useState(null);
  const [lightboxZoom, setLightboxZoom] = useState(1);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [documentImages, setDocumentImages] = useState([]);
  const [verifyingDoc, setVerifyingDoc] = useState(null);
  const [docVerification, setDocVerification] = useState({
    status: '',
    rejectionReason: ''
  });
  const [confirmDialog, setConfirmDialog] = useState({ open: false, type: null, app: null });
  const [rejectionReason, setRejectionReason] = useState('');
  const [showRejectionInput, setShowRejectionInput] = useState(false);
  const [requestDocsDialog, setRequestDocsDialog] = useState(false);
  const [requestedDocs, setRequestedDocs] = useState('');
  const [stats, setStats] = useState({
    pending: 0,
    submitted: 0,
    under_review: 0,
    partially_verified: 0,
    verified: 0,
    rejected: 0,
    todayVerified: 0,
    total: 0,
  });
  const [pagination, setPagination] = useState({
    page: 1,
    total: 0,
    pages: 1,
  });

  useEffect(() => {
    fetchStats();
    fetchApplications();
  }, [activeTab, pagination.page]);

  const fetchStats = async () => {
    try {
      const response = await axios.get(`${API_BASE_URL}/api/verification/stats`);
      if (response.data.success) {
        setStats(response.data.data);
      }
    } catch (error) {
      console.error('Error fetching stats:', error);
    }
  };

  const fetchApplications = async () => {
    setLoading(true);
    try {
      const status = activeTab === 'all' ? '' : activeTab;
      const url = `${API_BASE_URL}/api/verification/applications?page=${pagination.page}&limit=10${status ? `&status=${status}` : ''}`;
      
      const response = await axios.get(url);
      
      if (response.data.success) {
        setApplications(response.data.data);
        setPagination(response.data.pagination);
      }
    } catch (error) {
      toast.error('Failed to fetch applications');
      console.error('Error fetching applications:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleViewApplication = async (id) => {
    setLoading(true);
    try {
      const response = await axios.get(`${API_BASE_URL}/api/verification/applications/${id}`);
      
      if (response.data.success) {
        setSelectedApp(response.data.data);
        const docs = getDocumentFields(response.data.data);
        setDocumentImages(docs);
        setVerifyingDoc(null);
        setDocVerification({ status: '', rejectionReason: '' });
        setShowRejectionInput(false);
        setRejectionReason('');
        setDrawerOpen(true);
      }
    } catch (error) {
      toast.error('Failed to load application details');
    } finally {
      setLoading(false);
    }
  };

  const handleCloseDrawer = () => {
    setDrawerOpen(false);
    setSelectedApp(null);
    setDocumentImages([]);
    setVerifyingDoc(null);
    setShowRejectionInput(false);
  };

  const handleOpenLightbox = (image, index) => {
    setLightboxImage(image);
    setCurrentImageIndex(index);
    setLightboxZoom(1);
    setLightboxOpen(true);
  };

  const handleCloseLightbox = () => {
    setLightboxOpen(false);
    setLightboxImage(null);
    setLightboxZoom(1);
  };

  const handleZoomIn = () => {
    setLightboxZoom(prev => Math.min(prev + 0.5, 3));
  };

  const handleZoomOut = () => {
    setLightboxZoom(prev => Math.max(prev - 0.5, 0.5));
  };

  const handlePreviousImage = () => {
    const newIndex = currentImageIndex > 0 ? currentImageIndex - 1 : documentImages.length - 1;
    setCurrentImageIndex(newIndex);
    setLightboxImage(documentImages[newIndex].url);
    setLightboxZoom(1);
  };

  const handleNextImage = () => {
    const newIndex = currentImageIndex < documentImages.length - 1 ? currentImageIndex + 1 : 0;
    setCurrentImageIndex(newIndex);
    setLightboxImage(documentImages[newIndex].url);
    setLightboxZoom(1);
  };

  const handleVerifyDocument = async (docType) => {
    if (docVerification.status === 'rejected' && !docVerification.rejectionReason) {
      toast.error('Please provide rejection reason');
      return;
    }

    setLoading(true);
    try {
      const response = await axios.put(
        `${API_BASE_URL}/api/verification/applications/${selectedApp._id}/documents/${docType}/verify`,
        {
          status: docVerification.status,
          rejectionReason: docVerification.rejectionReason
        }
      );
      
      if (response.data.success) {
        toast.success(`Document ${docVerification.status}`);
        
        // Refresh application data
        const appResponse = await axios.get(`${API_BASE_URL}/api/verification/applications/${selectedApp._id}`);
        setSelectedApp(appResponse.data.data);
        setDocumentImages(getDocumentFields(appResponse.data.data));
        setVerifyingDoc(null);
        setDocVerification({ status: '', rejectionReason: '' });
        fetchStats();
        fetchApplications();
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to verify document');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyAll = async () => {
    setLoading(true);
    try {
      const response = await axios.put(`${API_BASE_URL}/api/verification/applications/${selectedApp._id}/verify`);
      
      if (response.data.success) {
        toast.success('Driver verified successfully');
        const appResponse = await axios.get(`${API_BASE_URL}/api/verification/applications/${selectedApp._id}`);
        setSelectedApp(appResponse.data.data);
        setDocumentImages(getDocumentFields(appResponse.data.data));
        fetchStats();
        fetchApplications();
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to verify driver');
    } finally {
      setLoading(false);
    }
  };

  const handleRejectAll = async () => {
    if (!rejectionReason.trim()) {
      toast.error('Please provide a rejection reason');
      return;
    }

    setLoading(true);
    try {
      const response = await axios.put(`${API_BASE_URL}/api/verification/applications/${selectedApp._id}/reject`, {
        reason: rejectionReason
      });
      
      if (response.data.success) {
        toast.success('Driver rejected');
        const appResponse = await axios.get(`${API_BASE_URL}/api/verification/applications/${selectedApp._id}`);
        setSelectedApp(appResponse.data.data);
        setDocumentImages(getDocumentFields(appResponse.data.data));
        setShowRejectionInput(false);
        setRejectionReason('');
        fetchStats();
        fetchApplications();
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to reject driver');
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = async (id, newStatus) => {
    setLoading(true);
    try {
      const response = await axios.patch(`${API_BASE_URL}/api/verification/applications/${id}/status`, {
        status: newStatus
      });
      
      if (response.data.success) {
        toast.success(`Status updated to ${newStatus}`);
        fetchStats();
        fetchApplications();
        if (selectedApp && selectedApp._id === id) {
          setSelectedApp(response.data.data);
        }
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to update status');
    } finally {
      setLoading(false);
    }
  };

  const maskAccountNumber = (number) => {
    if (!number) return '';
    return 'XXXX' + number.slice(-4);
  };

  const maskAadharNumber = (number) => {
    if (!number) return '';
    return 'XXXX XXXX ' + number.slice(-4);
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleDateString('en-IN', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    });
  };

  const handlePageChange = (event, value) => {
    setPagination(prev => ({ ...prev, page: value }));
  };

  const getDocumentFields = (app) => {
    const docs = [];
    
    const addDocument = (type, name, url, details = {}) => {
      if (url) {
        let status = 'pending';
        let rejectionReason = null;
        
        if (type === 'bankDetails') {
          status = app.bankDetails?.verification?.status || 'pending';
          rejectionReason = app.bankDetails?.verification?.rejectionReason;
        } else if (app[type]?.verification) {
          status = app[type].verification.status || 'pending';
          rejectionReason = app[type].verification.rejectionReason;
        }
        
        docs.push({
          type,
          name,
          url,
          status,
          rejectionReason,
          ...details
        });
      }
    };

    addDocument('profilePhoto', 'Profile Photo', app.profilePhoto?.url);
    
    // Enhanced Aadhar Card with number display
    addDocument('aadharCard', 'Aadhar Card', app.aadharCard?.url, { 
      number: app.aadharCard?.aadharNumber,
      maskedNumber: maskAadharNumber(app.aadharCard?.aadharNumber)
    });
    
    addDocument('panCard', 'PAN Card', app.panCard?.url);
    addDocument('drivingLicense', 'Driving License', app.drivingLicense?.url, { 
      number: app.drivingLicense?.licenseNumber,
      expiry: app.drivingLicense?.expiryDate 
    });
    addDocument('vehicleRC', 'Vehicle RC', app.vehicleRC?.url, { 
      number: app.vehicleRC?.rcNumber 
    });
    addDocument('vehicleInsurance', 'Insurance', app.vehicleInsurance?.url, { 
      policy: app.vehicleInsurance?.policyNumber,
      expiry: app.vehicleInsurance?.expiryDate 
    });
    addDocument('vehiclePhoto', 'Vehicle Photo', app.vehiclePhoto?.url);

    return docs;
  };

  const calculateProgress = () => {
    if (!selectedApp) return 0;
    const documents = getDocumentFields(selectedApp);
    const verifiedCount = documents.filter(doc => doc.status === 'verified').length;
    return documents.length > 0 ? (verifiedCount / documents.length) * 100 : 0;
  };

  const getDocumentIcon = (docType) => {
    switch(docType) {
      case 'aadharCard':
        return <AadharIcon sx={{ fontSize: 40, color: 'primary.main' }} />;
      case 'panCard':
        return <DocumentIcon sx={{ fontSize: 40, color: 'warning.main' }} />;
      case 'drivingLicense':
        return <DocumentIcon sx={{ fontSize: 40, color: 'success.main' }} />;
      case 'vehicleRC':
        return <VehicleIcon sx={{ fontSize: 40, color: 'info.main' }} />;
      case 'vehicleInsurance':
        return <DocumentIcon sx={{ fontSize: 40, color: 'secondary.main' }} />;
      default:
        return <DocumentIcon sx={{ fontSize: 40, color: 'text.secondary' }} />;
    }
  };

  // Document Card Component with inline verification
  const DocumentCard = ({ doc, index }) => {
    const [isHovered, setIsHovered] = useState(false);
    const [position, setPosition] = useState({ x: 0, y: 0 });

    const handleMouseMove = (e) => {
      const rect = e.currentTarget.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 100;
      const y = ((e.clientY - rect.top) / rect.height) * 100;
      setPosition({ x, y });
    };

    const isVerifying = verifyingDoc === doc.type;

    return (
      <Grid item xs={12} sm={6} md={4} key={index}>
        <Paper sx={{ p: 1, position: 'relative' }}>
          {/* Document Image with Zoom */}
          <Box
            sx={{
              position: 'relative',
              width: '100%',
              height: 150,
              overflow: 'hidden',
              borderRadius: 1,
              cursor: 'zoom-in',
              mb: 1,
              border: doc.status === 'rejected' ? '2px solid #f44336' : 
                      doc.status === 'verified' ? '2px solid #4caf50' : 'none',
            }}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
            onMouseMove={handleMouseMove}
            onClick={() => handleOpenLightbox(doc.url, index)}
          >
            <Box
              component="img"
              src={doc.url}
              alt={doc.name}
              sx={{
                width: '100%',
                height: '100%',
                objectFit: 'cover',
                transition: 'transform 0.3s ease',
                transform: isHovered ? 'scale(2)' : 'scale(1)',
                transformOrigin: `${position.x}% ${position.y}%`,
              }}
            />
            {isHovered && (
              <Box sx={{ position: 'absolute', top: 8, right: 8, bgcolor: 'rgba(0,0,0,0.6)', color: 'white', borderRadius: 1, p: 0.5 }}>
                <ZoomInIcon fontSize="small" />
              </Box>
            )}
            <Box sx={{ position: 'absolute', top: 8, left: 8 }}>
              <Chip
                size="small"
                label={doc.status.toUpperCase()}
                color={doc.status === 'verified' ? 'success' : doc.status === 'rejected' ? 'error' : 'warning'}
                sx={{ height: 20, '& .MuiChip-label': { px: 1, fontSize: '0.7rem' } }}
              />
            </Box>
          </Box>

          {/* Document Info */}
          <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>
            {doc.name}
          </Typography>
          
          {/* Aadhar Number Display */}
          {doc.type === 'aadharCard' && doc.number && (
            <Box sx={{ mt: 0.5, mb: 1 }}>
              <Typography variant="caption" sx={{ color: 'text.secondary', display: 'block' }}>
                Aadhar Number:
              </Typography>
              <Typography variant="body2" sx={{ fontWeight: 600, fontFamily: 'monospace', fontSize: '0.9rem' }}>
                {doc.maskedNumber || doc.number}
              </Typography>
            </Box>
          )}
          
          {/* Other document numbers */}
          {doc.type !== 'aadharCard' && doc.number && (
            <Typography variant="caption" sx={{ color: 'text.secondary', display: 'block' }}>
              {doc.type === 'drivingLicense' ? 'License: ' : 
               doc.type === 'vehicleRC' ? 'RC: ' : 
               doc.type === 'vehicleInsurance' ? 'Policy: ' : ''}
              {doc.number}
            </Typography>
          )}
          
          {doc.policy && (
            <Typography variant="caption" sx={{ color: 'text.secondary', display: 'block' }}>
              Policy: {doc.policy}
            </Typography>
          )}
          {doc.expiry && (
            <Typography variant="caption" sx={{ color: 'success.main', display: 'block' }}>
              Exp: {formatDate(doc.expiry)}
            </Typography>
          )}

          {/* Rejection Reason */}
          {doc.status === 'rejected' && doc.rejectionReason && (
            <Alert severity="error" sx={{ mt: 1, py: 0, '& .MuiAlert-message': { fontSize: '0.75rem' } }}>
              {doc.rejectionReason}
            </Alert>
          )}

          {/* Verification Controls - Below each image */}
          {isVerifying ? (
            <Box sx={{ mt: 2 }}>
              <FormControl component="fieldset" size="small" fullWidth>
                <RadioGroup
                  row
                  value={docVerification.status}
                  onChange={(e) => setDocVerification({ ...docVerification, status: e.target.value })}
                >
                  <FormControlLabel value="verified" control={<Radio size="small" />} label="Verify" />
                  <FormControlLabel value="rejected" control={<Radio size="small" />} label="Reject" />
                </RadioGroup>
              </FormControl>

              {docVerification.status === 'rejected' && (
                <TextField
                  size="small"
                  fullWidth
                  placeholder="Rejection reason"
                  value={docVerification.rejectionReason}
                  onChange={(e) => setDocVerification({ ...docVerification, rejectionReason: e.target.value })}
                  sx={{ mt: 1 }}
                />
              )}

              <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
                <Button
                  size="small"
                  variant="contained"
                  color="primary"
                  onClick={() => handleVerifyDocument(doc.type)}
                  disabled={!docVerification.status}
                >
                  Submit
                </Button>
                <Button
                  size="small"
                  variant="outlined"
                  onClick={() => {
                    setVerifyingDoc(null);
                    setDocVerification({ status: '', rejectionReason: '' });
                  }}
                >
                  Cancel
                </Button>
              </Box>
            </Box>
          ) : (
            <Button
              fullWidth
              size="small"
              variant="outlined"
              onClick={() => {
                setVerifyingDoc(doc.type);
                setDocVerification({ status: '', rejectionReason: '' });
              }}
              sx={{ mt: 1 }}
            >
              Verify This Document
            </Button>
          )}
        </Paper>
      </Grid>
    );
  };

  // Compact Document Card for Summary View
  const CompactDocumentCard = ({ doc }) => {
    return (
      <Paper sx={{ p: 2, display: 'flex', alignItems: 'center', gap: 2 }}>
        {getDocumentIcon(doc.type)}
        <Box sx={{ flex: 1 }}>
          <Typography variant="subtitle2">{doc.name}</Typography>
          {doc.type === 'aadharCard' && doc.number && (
            <Typography variant="caption" sx={{ fontFamily: 'monospace', display: 'block' }}>
              {doc.maskedNumber || doc.number}
            </Typography>
          )}
          {doc.number && doc.type !== 'aadharCard' && (
            <Typography variant="caption" color="text.secondary">
              {doc.number}
            </Typography>
          )}
        </Box>
        <Chip
          size="small"
          label={doc.status}
          color={doc.status === 'verified' ? 'success' : doc.status === 'rejected' ? 'error' : 'warning'}
          icon={doc.status === 'verified' ? <VerifiedIcon /> : doc.status === 'rejected' ? <RejectedIcon /> : <PendingIcon />}
        />
      </Paper>
    );
  };

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" sx={{ fontWeight: 700, mb: 1 }}>
          Driver Verification
        </Typography>
        <Typography variant="body1" sx={{ color: 'text.secondary' }}>
          Review and verify driver applications including Aadhar cards and other documents
        </Typography>
      </Box>

      {/* Stats Cards */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={2.4}>
          <Card>
            <CardContent>
              <Typography variant="subtitle2" color="text.secondary">Pending</Typography>
              <Typography variant="h4">{stats.pending}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={2.4}>
          <Card>
            <CardContent>
              <Typography variant="subtitle2" color="text.secondary">Submitted</Typography>
              <Typography variant="h4">{stats.submitted}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={2.4}>
          <Card>
            <CardContent>
              <Typography variant="subtitle2" color="text.secondary">Under Review</Typography>
              <Typography variant="h4">{stats.under_review}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={2.4}>
          <Card>
            <CardContent>
              <Typography variant="subtitle2" color="text.secondary">Partially Verified</Typography>
              <Typography variant="h4">{stats.partially_verified || 0}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={2.4}>
          <Card>
            <CardContent>
              <Typography variant="subtitle2" color="text.secondary">Verified</Typography>
              <Typography variant="h4">{stats.verified}</Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Tabs and Table */}
      <Card>
        <Tabs
          value={activeTab}
          onChange={(e, newValue) => {
            setActiveTab(newValue);
            setPagination(prev => ({ ...prev, page: 1 }));
          }}
          sx={{ borderBottom: 1, borderColor: 'divider' }}
          variant="scrollable"
          scrollButtons="auto"
        >
          <Tab label="All" value="all" />
          <Tab label={`Pending (${stats.pending})`} value="pending" />
          <Tab label={`Submitted (${stats.submitted})`} value="submitted" />
          <Tab label={`Under Review (${stats.under_review})`} value="under_review" />
          <Tab label={`Partially Verified (${stats.partially_verified || 0})`} value="partially_verified" />
          <Tab label={`Verified (${stats.verified})`} value="verified" />
          <Tab label={`Rejected (${stats.rejected})`} value="rejected" />
        </Tabs>

        <CardContent sx={{ p: 0 }}>
          {loading && applications.length === 0 ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
              <CircularProgress />
            </Box>
          ) : (
            <>
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>Driver</TableCell>
                      <TableCell>Phone</TableCell>
                      <TableCell>Documents</TableCell>
                      <TableCell>Aadhar Status</TableCell>
                      <TableCell>Submitted</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell align="center">Actions</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {applications.map((app) => {
                      const docs = getDocumentFields(app);
                      const verifiedCount = docs.filter(d => d.status === 'verified').length;
                      const rejectedCount = docs.filter(d => d.status === 'rejected').length;
                      const pendingCount = docs.filter(d => d.status === 'pending').length;
                      const aadharDoc = docs.find(d => d.type === 'aadharCard');
                      
                      return (
                        <TableRow key={app._id} hover sx={{ cursor: 'pointer' }} onClick={() => handleViewApplication(app._id)}>
                          <TableCell>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                              <Avatar src={app.profilePhoto?.url} alt={app.fullName}>
                                {app.fullName?.charAt(0)}
                              </Avatar>
                              <Box>
                                <Typography variant="body2" sx={{ fontWeight: 600 }}>
                                  {app.fullName}
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                  {app.email}
                                </Typography>
                              </Box>
                            </Box>
                          </TableCell>
                          <TableCell>{app.phone}</TableCell>
                          <TableCell>
                            <Stack direction="row" spacing={1}>
                              {verifiedCount > 0 && (
                                <Chip size="small" label={`✓${verifiedCount}`} color="success" variant="outlined" />
                              )}
                              {rejectedCount > 0 && (
                                <Chip size="small" label={`✗${rejectedCount}`} color="error" variant="outlined" />
                              )}
                              {pendingCount > 0 && (
                                <Chip size="small" label={`⏳${pendingCount}`} color="warning" variant="outlined" />
                              )}
                            </Stack>
                          </TableCell>
                          <TableCell>
                            {aadharDoc ? (
                              <Chip
                                size="small"
                                label={aadharDoc.status}
                                color={aadharDoc.status === 'verified' ? 'success' : aadharDoc.status === 'rejected' ? 'error' : 'warning'}
                                icon={aadharDoc.status === 'verified' ? <VerifiedIcon /> : aadharDoc.status === 'rejected' ? <RejectedIcon /> : <PendingIcon />}
                              />
                            ) : (
                              <Chip size="small" label="Not Uploaded" color="default" />
                            )}
                          </TableCell>
                          <TableCell>{formatDate(app.submittedAt || app.createdAt)}</TableCell>
                          <TableCell>
                            <Chip
                              icon={statusConfig[app.verificationStatus]?.icon}
                              label={statusConfig[app.verificationStatus]?.label}
                              color={statusConfig[app.verificationStatus]?.color}
                              size="small"
                            />
                          </TableCell>
                          <TableCell align="center">
                            <Tooltip title="View Details">
                              <IconButton size="small" onClick={(e) => { e.stopPropagation(); handleViewApplication(app._id); }}>
                                <ViewIcon fontSize="small" />
                              </IconButton>
                            </Tooltip>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </TableContainer>

              {pagination.pages > 1 && (
                <Box sx={{ display: 'flex', justifyContent: 'center', p: 2 }}>
                  <Pagination count={pagination.pages} page={pagination.page} onChange={handlePageChange} color="primary" />
                </Box>
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* Detail Drawer */}
      <Drawer
        anchor="right"
        open={drawerOpen}
        onClose={handleCloseDrawer}
        PaperProps={{ sx: { width: { xs: '100%', sm: 700, md: 800 } } }}
      >
        {selectedApp && (
          <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Drawer Header */}
            <Box sx={{ p: 3, borderBottom: 1, borderColor: 'divider', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <Box>
                <Typography variant="h6" sx={{ fontWeight: 700 }}>
                  {selectedApp.fullName}
                </Typography>
                <Chip
                  icon={statusConfig[selectedApp.verificationStatus]?.icon}
                  label={statusConfig[selectedApp.verificationStatus]?.label}
                  color={statusConfig[selectedApp.verificationStatus]?.color}
                  size="small"
                  sx={{ mt: 1 }}
                />
              </Box>
              <IconButton onClick={handleCloseDrawer}>
                <CloseIcon />
              </IconButton>
            </Box>

            {/* Drawer Content */}
            <Box sx={{ flex: 1, overflow: 'auto', p: 3 }}>
              {/* Progress Bar */}
              <Card sx={{ mb: 3 }}>
                <CardContent>
                  <Typography variant="subtitle2" sx={{ mb: 1 }}>Verification Progress</Typography>
                  <LinearProgress 
                    variant="determinate" 
                    value={calculateProgress()} 
                    color="success"
                    sx={{ height: 8, borderRadius: 4, mb: 1 }}
                  />
                  <Typography variant="caption" color="text.secondary">
                    {getDocumentFields(selectedApp).filter(d => d.status === 'verified').length} of {getDocumentFields(selectedApp).length} documents verified
                  </Typography>
                </CardContent>
              </Card>

              {/* Personal Info */}
              <Card sx={{ mb: 3 }}>
                <CardContent>
                  <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
                    Personal Information
                  </Typography>
                  <Grid container spacing={2}>
                    <Grid item xs={12} sm={6}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <EmailIcon sx={{ color: 'text.secondary', fontSize: 20 }} />
                        <Typography variant="body2">{selectedApp.email}</Typography>
                      </Box>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <PhoneIcon sx={{ color: 'text.secondary', fontSize: 20 }} />
                        <Typography variant="body2">{selectedApp.phone}</Typography>
                      </Box>
                    </Grid>
                    {selectedApp.dateOfBirth && (
                      <Grid item xs={12} sm={6}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <CalendarIcon sx={{ color: 'text.secondary', fontSize: 20 }} />
                          <Typography variant="body2">DOB: {formatDate(selectedApp.dateOfBirth)}</Typography>
                        </Box>
                      </Grid>
                    )}
                  </Grid>
                </CardContent>
              </Card>

              {/* Documents Grid */}
              <Card sx={{ mb: 3 }}>
                <CardContent>
                  <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
                    Documents
                  </Typography>
                  <Grid container spacing={2}>
                    {documentImages.map((doc, index) => (
                      <DocumentCard key={index} doc={doc} index={index} />
                    ))}
                  </Grid>
                </CardContent>
              </Card>

              {/* Vehicle Info */}
              {(selectedApp.vehicleType || selectedApp.vehicleNumber) && (
                <Card sx={{ mb: 3 }}>
                  <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
                      Vehicle Information
                    </Typography>
                    <Grid container spacing={2}>
                      {selectedApp.vehicleType && (
                        <Grid item xs={6}>
                          <Typography variant="caption" color="text.secondary">Type</Typography>
                          <Typography variant="body2" sx={{ fontWeight: 600 }}>{selectedApp.vehicleType}</Typography>
                        </Grid>
                      )}
                      {selectedApp.vehicleNumber && (
                        <Grid item xs={6}>
                          <Typography variant="caption" color="text.secondary">Number</Typography>
                          <Typography variant="body2" sx={{ fontWeight: 600 }}>{selectedApp.vehicleNumber}</Typography>
                        </Grid>
                      )}
                      {selectedApp.vehicleModel && (
                        <Grid item xs={6}>
                          <Typography variant="caption" color="text.secondary">Model</Typography>
                          <Typography variant="body2">{selectedApp.vehicleModel}</Typography>
                        </Grid>
                      )}
                      {selectedApp.vehicleYear && (
                        <Grid item xs={6}>
                          <Typography variant="caption" color="text.secondary">Year</Typography>
                          <Typography variant="body2">{selectedApp.vehicleYear}</Typography>
                        </Grid>
                      )}
                    </Grid>
                  </CardContent>
                </Card>
              )}

              {/* Bank Details */}
              {selectedApp.bankDetails && (
                <Card sx={{ mb: 3 }}>
                  <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
                      Bank Details
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} sm={6}>
                        <Typography variant="caption" color="text.secondary">Account Holder</Typography>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>{selectedApp.bankDetails.accountHolderName}</Typography>
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <Typography variant="caption" color="text.secondary">Account Number</Typography>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>{maskAccountNumber(selectedApp.bankDetails.accountNumber)}</Typography>
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <Typography variant="caption" color="text.secondary">IFSC Code</Typography>
                        <Typography variant="body2">{selectedApp.bankDetails.ifscCode}</Typography>
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <Typography variant="caption" color="text.secondary">Bank Name</Typography>
                        <Typography variant="body2">{selectedApp.bankDetails.bankName}</Typography>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>
              )}
            </Box>

            {/* Overall Actions */}
            <Box sx={{ p: 3, borderTop: 1, borderColor: 'divider', bgcolor: 'background.paper' }}>
              {!showRejectionInput ? (
                <Box sx={{ display: 'flex', gap: 2 }}>
                  <Button
                    fullWidth
                    variant="contained"
                    color="success"
                    startIcon={<VerifyIcon />}
                    onClick={handleVerifyAll}
                    disabled={loading}
                  >
                    Approve All
                  </Button>
                  <Button
                    fullWidth
                    variant="outlined"
                    color="error"
                    startIcon={<RejectIcon />}
                    onClick={() => setShowRejectionInput(true)}
                    disabled={loading}
                  >
                    Reject All
                  </Button>
                </Box>
              ) : (
                <>
                  <TextField
                    fullWidth
                    multiline
                    rows={2}
                    placeholder="Enter rejection reason..."
                    value={rejectionReason}
                    onChange={(e) => setRejectionReason(e.target.value)}
                    sx={{ mb: 2 }}
                  />
                  <Box sx={{ display: 'flex', gap: 2 }}>
                    <Button
                      fullWidth
                      variant="contained"
                      color="error"
                      onClick={handleRejectAll}
                      disabled={loading}
                    >
                      Confirm Rejection
                    </Button>
                    <Button
                      fullWidth
                      variant="outlined"
                      onClick={() => {
                        setShowRejectionInput(false);
                        setRejectionReason('');
                      }}
                    >
                      Cancel
                    </Button>
                  </Box>
                </>
              )}
            </Box>
          </Box>
        )}
      </Drawer>

      {/* Image Lightbox */}
      <Modal 
        open={lightboxOpen} 
        onClose={handleCloseLightbox} 
        closeAfterTransition 
        BackdropComponent={Backdrop}
        BackdropProps={{ timeout: 500 }}
      >
        <Fade in={lightboxOpen}>
          <Box sx={{ 
            position: 'absolute', 
            top: '50%', 
            left: '50%', 
            transform: 'translate(-50%, -50%)', 
            bgcolor: 'background.paper', 
            boxShadow: 24, 
            p: 2, 
            maxWidth: '90vw', 
            maxHeight: '90vh', 
            outline: 'none', 
            borderRadius: 2 
          }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="subtitle1">
                {documentImages[currentImageIndex]?.name} • {currentImageIndex + 1} / {documentImages.length}
              </Typography>
              <Box>
                <IconButton onClick={handleZoomIn} size="small">
                  <ZoomInIcon />
                </IconButton>
                <IconButton onClick={handleZoomOut} size="small">
                  <ZoomOutIcon />
                </IconButton>
                <IconButton onClick={handleCloseLightbox} size="small">
                  <CloseIcon />
                </IconButton>
              </Box>
            </Box>
            <Box sx={{ width: '80vw', height: '70vh', overflow: 'hidden' }}>
              <Box
                component="img"
                src={lightboxImage}
                alt="Document"
                sx={{ 
                  width: '100%', 
                  height: '100%', 
                  objectFit: 'contain', 
                  transform: `scale(${lightboxZoom})`, 
                  transition: 'transform 0.1s ease' 
                }}
              />
            </Box>
            {documentImages.length > 1 && (
              <>
                <IconButton 
                  onClick={handlePreviousImage} 
                  sx={{ 
                    position: 'absolute', 
                    left: 16, 
                    top: '50%', 
                    bgcolor: 'rgba(0,0,0,0.5)', 
                    color: 'white',
                    '&:hover': { bgcolor: 'rgba(0,0,0,0.7)' }
                  }}
                >
                  <ArrowBackIcon />
                </IconButton>
                <IconButton 
                  onClick={handleNextImage} 
                  sx={{ 
                    position: 'absolute', 
                    right: 16, 
                    top: '50%', 
                    bgcolor: 'rgba(0,0,0,0.5)', 
                    color: 'white',
                    '&:hover': { bgcolor: 'rgba(0,0,0,0.7)' }
                  }}
                >
                  <ArrowForwardIcon />
                </IconButton>
              </>
            )}
          </Box>
        </Fade>
      </Modal>
    </Box>
  );
};

export default DriverVerification;