import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { io } from 'socket.io-client';

const AppContext = createContext();

const API_URL = process.env.REACT_APP_API_URL || 'https://godelivo.com';

export const AppProvider = ({ children }) => {
  const [socket, setSocket] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [stats, setStats] = useState({
    totalOrders: 0,
    pendingOrders: 0,
    activeOrders: 0,
    completedOrders: 0,
    totalDrivers: 0,
    onlineDrivers: 0,
    totalCustomers: 0,
    todayOrders: 0,
  });

  useEffect(() => {
    // Connect to admin namespace
    const newSocket = io(`${API_URL}/admin`);
    
    newSocket.on('connect', () => {
      console.log('Socket connected to admin namespace:', newSocket.id);
      setIsConnected(true);
    });

    newSocket.on('disconnect', () => {
      console.log('Socket disconnected from admin namespace');
      setIsConnected(false);
    });

    // Dashboard stats update
    newSocket.on('dashboard:stats-update', (data) => {
      setStats(data);
    });

    // Booking events
    newSocket.on('booking:new', (data) => {
      addNotification('New Booking', `Booking #${data.order?.bookingId || 'Unknown'} created`, 'info');
    });

    newSocket.on('booking:assigned', (data) => {
      addNotification('Driver Assigned', `Booking #${data.order?.bookingId || 'Unknown'} assigned`, 'success');
    });

    newSocket.on('booking:status-updated', (data) => {
      addNotification('Status Update', `Booking status changed to ${data.status || data.newStatus}`, 'warning');
    });

    newSocket.on('booking:completed', (data) => {
      addNotification('Booking Completed', `Booking #${data.orderId || 'Unknown'} completed`, 'success');
    });

    newSocket.on('booking:cancelled', (data) => {
      addNotification('Booking Cancelled', `Booking #${data.orderId || 'Unknown'} cancelled`, 'error');
    });

    // Driver events
    newSocket.on('driver:online', (data) => {
      addNotification('Driver Online', `Driver ${data.driverId} came online`, 'success');
    });

    newSocket.on('driver:offline', (data) => {
      addNotification('Driver Offline', `Driver ${data.driverId} went offline`, 'info');
    });

    newSocket.on('driver:location-update', (data) => {
      // Silent update for map
    });

    newSocket.on('driver:availability-update', (data) => {
      addNotification('Driver Status', `Driver ${data.driverId} is now ${data.isAvailable ? 'available' : 'busy'}`, 'info');
    });

    setSocket(newSocket);

    return () => newSocket.close();
  }, []);

  const addNotification = (title, message, type = 'info') => {
    const newNotification = {
      id: Date.now(),
      title,
      message,
      type,
      timestamp: new Date(),
    };
    setNotifications((prev) => [newNotification, ...prev].slice(0, 50));
  };

  const clearNotifications = () => {
    setNotifications([]);
  };

  const removeNotification = (id) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  };

  const value = {
    socket,
    isConnected,
    notifications,
    stats,
    addNotification,
    clearNotifications,
    removeNotification,
    API_URL,
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
};

export default AppContext;
