import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Typography,
  Switch,
  CircularProgress,
  Chip,
} from '@mui/material';
import {
  SignalCellularAlt as OnlineIcon,
  SignalCellularOff as OfflineIcon,
} from '@mui/icons-material';
import driverApi from '../services/driverApi';
import driverSocketService from '../services/driverSocket';

const LiveOfflineToggle = ({ driverId, initialStatus = false, onStatusChange }) => {
  const [isOnline, setIsOnline] = useState(initialStatus);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    setIsOnline(initialStatus);
  }, [initialStatus]);

  const handleToggle = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const newStatus = !isOnline;
      const response = await driverApi.toggleOnlineStatus(newStatus);

      if (response.success) {
        setIsOnline(newStatus);

        if (newStatus) {
          driverSocketService.connect(driverId);
        } else {
          driverSocketService.disconnect();
        }

        if (onStatusChange) {
          onStatusChange(newStatus);
        }
      }
    } catch (err) {
      setError(err.message || 'Failed to update status');
    } finally {
      setIsLoading(false);
    }
  }, [isOnline, driverId, onStatusChange]);

  return (
    <Box
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        p: 2,
        borderRadius: 2,
        bgcolor: isOnline ? 'rgba(46, 125, 50, 0.1)' : 'rgba(158, 158, 158, 0.1)',
        border: `2px solid ${isOnline ? '#2E7D32' : '#9E9E9E'}`,
        transition: 'all 0.3s ease',
      }}
    >
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
        {isLoading ? (
          <CircularProgress size={24} sx={{ color: '#FFB300' }} />
        ) : isOnline ? (
          <OnlineIcon sx={{ color: '#2E7D32', fontSize: 28 }} />
        ) : (
          <OfflineIcon sx={{ color: '#9E9E9E', fontSize: 28 }} />
        )}
        <Box>
          <Typography
            variant="body1"
            sx={{
              fontWeight: 700,
              color: isOnline ? '#2E7D32' : '#9E9E9E',
            }}
          >
            {isOnline ? 'LIVE' : 'OFFLINE'}
          </Typography>
          <Typography variant="caption" color="text.secondary">
            {isOnline
              ? 'You are visible to customers'
              : 'You are not visible to customers'}
          </Typography>
        </Box>
      </Box>

      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
        <Chip
          label={isOnline ? 'Online' : 'Offline'}
          size="small"
          sx={{
            bgcolor: isOnline ? '#2E7D32' : '#9E9E9E',
            color: '#fff',
            fontWeight: 600,
          }}
        />
        <Switch
          checked={isOnline}
          onChange={handleToggle}
          disabled={isLoading}
          sx={{
            '& .MuiSwitch-switchBase.Mui-checked': {
              color: '#2E7D32',
            },
            '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': {
              backgroundColor: '#2E7D32',
            },
          }}
        />
      </Box>

      {error && (
        <Typography variant="caption" color="error" sx={{ mt: 1, display: 'block' }}>
          {error}
        </Typography>
      )}
    </Box>
  );
};

export default LiveOfflineToggle;
