// pages/PaymentTester.jsx
import React, { useState, useEffect } from 'react';
import './PaymentTester.css';

const API_BASE_URL = 'https://godelivo.com/api';

const PaymentTester = () => {
  const [authToken, setAuthToken] = useState('');
  const [rideId, setRideId] = useState('RID02360983578'); // Your test ride ID
  const [loading, setLoading] = useState(false);
  const [orderData, setOrderData] = useState(null);
  const [verificationData, setVerificationData] = useState(null);
  const [paymentResult, setPaymentResult] = useState(null);
  const [activeStep, setActiveStep] = useState(1);
  const [webhookResponse, setWebhookResponse] = useState(null);
  const [refundData, setRefundData] = useState(null);
  const [paymentHistory, setPaymentHistory] = useState([]);
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [refreshInterval, setRefreshInterval] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState('upi');

  // Manual payment details entry
  const [manualPayment, setManualPayment] = useState({
    paymentId: '',
    orderId: '',
    signature: ''
  });

  // UPI details
  const [upiDetails, setUpiDetails] = useState({
    vpa: 'customer@okhdfcbank',
    transactionId: ''
  });

  // Webhook test data
  const [webhookPayload, setWebhookPayload] = useState({
    event: 'payment.captured',
    paymentId: '',
    orderId: '',
    amount: 0
  });

  // Load payment history from localStorage on component mount
  useEffect(() => {
    const savedHistory = localStorage.getItem('paymentHistory');
    if (savedHistory) {
      setPaymentHistory(JSON.parse(savedHistory));
    }
  }, []);

  // Auto-refresh status
  useEffect(() => {
    if (autoRefresh && authToken && rideId) {
      const interval = setInterval(() => {
        checkStatus(true);
      }, 5000);
      setRefreshInterval(interval);
    }
    return () => {
      if (refreshInterval) {
        clearInterval(refreshInterval);
      }
    };
  }, [autoRefresh, authToken, rideId]);

  const saveToHistory = (action, data) => {
    const historyItem = {
      id: Date.now(),
      timestamp: new Date().toISOString(),
      action,
      rideId,
      orderId: data?.orderId || manualPayment.orderId,
      status: data?.status || 'success',
      data
    };
    const updatedHistory = [historyItem, ...paymentHistory].slice(0, 20);
    setPaymentHistory(updatedHistory);
    localStorage.setItem('paymentHistory', JSON.stringify(updatedHistory));
  };

  const createOrder = async () => {
    if (!authToken || !rideId) {
      alert('Please enter Auth Token and Ride ID');
      return;
    }

    setLoading(true);
    setPaymentResult(null);
    try {
      console.log('📝 Creating payment order for ride:', rideId);
      const response = await fetch(`${API_BASE_URL}/payments/create-order`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${authToken}`
        },
        body: JSON.stringify({ rideId })
      });

      const data = await response.json();
      console.log('Create Order Response:', data);

      if (data.success) {
        setOrderData(data.data);
        setActiveStep(2);
        setManualPayment(prev => ({ ...prev, orderId: data.data.orderId }));
        setWebhookPayload(prev => ({ 
          ...prev, 
          orderId: data.data.orderId,
          amount: data.data.amount 
        }));
        saveToHistory('CREATE_ORDER', data.data);
        alert('✅ Order created successfully!');
      } else {
        alert('❌ Failed to create order: ' + data.message);
        saveToHistory('CREATE_ORDER_ERROR', { message: data.message });
      }
    } catch (error) {
      console.error('Error:', error);
      alert('Error creating order: ' + error.message);
      saveToHistory('CREATE_ORDER_ERROR', { message: error.message });
    } finally {
      setLoading(false);
    }
  };

  const generateUPIPaymentId = () => {
    // Generate a realistic UPI payment ID
    const timestamp = Date.now();
    const random = Math.floor(Math.random() * 10000);
    return `pay_UPI_${timestamp}_${random}`;
  };

  const generateSignature = (orderId, paymentId) => {
    // Generate signature using crypto (simulated for frontend)
    const body = orderId + "|" + paymentId;
    // In real app, this would be done on backend
    // This is just for testing
    const crypto = require('crypto-js');
    const signature = crypto.HmacSHA256(body, 'OZdye2d48zaLY1gSko96eJsX').toString();
    return signature;
  };

  const verifyPayment = async () => {
    if (!manualPayment.paymentId || !manualPayment.orderId || !manualPayment.signature) {
      alert('Please fill all payment details');
      return;
    }

    setLoading(true);
    try {
      console.log('🔍 Verifying payment...');
      const response = await fetch(`${API_BASE_URL}/payments/verify`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${authToken}`
        },
        body: JSON.stringify({
          rideId,
          razorpay_payment_id: manualPayment.paymentId,
          razorpay_order_id: manualPayment.orderId,
          razorpay_signature: manualPayment.signature
        })
      });

      const data = await response.json();
      console.log('Verify Payment Response:', data);

      if (data.success) {
        setVerificationData(data.data);
        setPaymentResult({ success: true, message: '✅ Payment verified successfully!' });
        setActiveStep(3);
        saveToHistory('VERIFY_PAYMENT', { ...data.data, paymentId: manualPayment.paymentId });
        alert('✅ Payment verified successfully!');
      } else {
        setPaymentResult({ success: false, message: '❌ ' + data.message });
        saveToHistory('VERIFY_PAYMENT_ERROR', { message: data.message });
      }
    } catch (error) {
      console.error('Error:', error);
      setPaymentResult({ success: false, message: '❌ ' + error.message });
      saveToHistory('VERIFY_PAYMENT_ERROR', { message: error.message });
    } finally {
      setLoading(false);
    }
  };

  const simulateUPIPayment = () => {
    // Simulate a UPI payment
    const paymentId = generateUPIPaymentId();
    const signature = generateSignature(manualPayment.orderId, paymentId);
    
    setManualPayment({
      ...manualPayment,
      paymentId: paymentId,
      signature: signature
    });

    setUpiDetails({
      ...upiDetails,
      transactionId: paymentId
    });

    alert('✅ UPI payment simulated! Click Verify Payment to complete.');
  };

  const checkStatus = async (silent = false) => {
    if (!authToken || !rideId) return;

    try {
      const response = await fetch(`${API_BASE_URL}/payments/${rideId}/status`, {
        headers: {
          'Authorization': `Bearer ${authToken}`
        }
      });

      const data = await response.json();
      console.log('Status Check:', data);
      
      if (data.success) {
        setPaymentResult({
          success: true,
          message: `Payment Status: ${data.data.paymentStatus}`
        });
        if (!silent) {
          saveToHistory('STATUS_CHECK', data.data);
        }
      }
    } catch (error) {
      console.error('Status check error:', error);
      if (!silent) {
        alert('Status check failed: ' + error.message);
      }
    }
  };

  const testWebhook = async () => {
    if (!webhookPayload.orderId) {
      alert('Please create an order first');
      return;
    }

    setLoading(true);
    try {
      const payload = {
        entity: "event",
        event: webhookPayload.event,
        payload: {
          payment: {
            entity: {
              id: webhookPayload.paymentId || 'pay_webhook_' + Date.now(),
              amount: webhookPayload.amount,
              currency: "INR",
              status: webhookPayload.event === 'payment.captured' ? 'captured' : 'failed',
              order_id: webhookPayload.orderId,
              method: "upi",
              vpa: "customer@okhdfcbank",
              email: "customer@example.com",
              contact: "+919876543210",
              notes: {
                rideId: rideId
              }
            }
          }
        },
        created_at: Math.floor(Date.now() / 1000)
      };

      console.log('📨 Sending webhook:', payload);
      
      const response = await fetch(`${API_BASE_URL}/payments/webhook/razorpay`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-razorpay-signature': generateSignature(webhookPayload.orderId, payload.payload.payment.entity.id)
        },
        body: JSON.stringify(payload)
      });

      const data = await response.json();
      console.log('Webhook Response:', data);
      
      setWebhookResponse({
        status: response.status,
        data: data
      });

      saveToHistory('WEBHOOK_TEST', { event: webhookPayload.event, response: data });
      
      if (response.ok) {
        alert('✅ Webhook sent successfully!');
        setTimeout(() => checkStatus(true), 2000);
      } else {
        alert('❌ Webhook failed: ' + JSON.stringify(data));
      }
    } catch (error) {
      console.error('Webhook error:', error);
      alert('Webhook error: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const processRefund = async () => {
    if (!orderData) {
      alert('Please create an order first');
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(`${API_BASE_URL}/payments/refund`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${authToken}`
        },
        body: JSON.stringify({
          rideId,
          reason: 'Test refund'
        })
      });

      const data = await response.json();
      console.log('Refund Response:', data);
      
      setRefundData(data);
      saveToHistory('REFUND', data);
      
      if (data.success) {
        alert('✅ Refund processed successfully!');
      } else {
        alert('❌ Refund failed: ' + data.message);
      }
    } catch (error) {
      console.error('Refund error:', error);
      alert('Refund error: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const clearHistory = () => {
    setPaymentHistory([]);
    localStorage.removeItem('paymentHistory');
  };

  const resetForm = () => {
    setOrderData(null);
    setVerificationData(null);
    setPaymentResult(null);
    setWebhookResponse(null);
    setRefundData(null);
    setManualPayment({ paymentId: '', orderId: '', signature: '' });
    setActiveStep(1);
  };

  // For your specific order
  const sampleTestData = {
    orderId: 'order_ST1VTP3zhprrC0',
    amount: 17500,
    paymentId: 'pay_upi_' + Date.now(),
    signature: 'test_signature_1234567890abcdef'
  };

  return (
    <div className="pt-container">
      <h1 className="pt-title">💳 Razorpay Payment Tester</h1>
      
      {/* Header Controls */}
      <div className="pt-header-controls">
        <button 
          className="pt-btn pt-btn-secondary"
          onClick={resetForm}
        >
          🔄 Reset Form
        </button>
        <button 
          className="pt-btn pt-btn-secondary"
          onClick={() => setAutoRefresh(!autoRefresh)}
        >
          {autoRefresh ? '⏹️ Stop Auto Refresh' : '🔄 Auto Refresh (5s)'}
        </button>
      </div>
      
      {/* Step 1: Authentication */}
      <div className="pt-step-card">
        <h2 className="pt-step-title">
          <span className="pt-step-number">1</span>
          Enter Credentials
        </h2>
        <div className="pt-input-group">
          <label className="pt-label">Auth Token (JWT):</label>
          <textarea
            className="pt-textarea"
            value={authToken}
            onChange={(e) => setAuthToken(e.target.value)}
            placeholder="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
            rows="3"
          />
          <small className="pt-hint">Paste your customer JWT token here</small>
        </div>

        <div className="pt-input-group">
          <label className="pt-label">Ride ID:</label>
          <input
            className="pt-input"
            type="text"
            value={rideId}
            onChange={(e) => setRideId(e.target.value)}
            placeholder="RID12345678"
          />
        </div>

        <div className="pt-quick-ride-buttons">
          <button 
            className="pt-btn pt-btn-small"
            onClick={() => setRideId('RID' + Date.now().toString().slice(-8))}
          >
            Generate New Ride ID
          </button>
          <button 
            className="pt-btn pt-btn-small"
            onClick={() => setRideId('RID02360983578')}
          >
            Use Test Ride (₹175)
          </button>
        </div>

        <button 
          className="pt-btn pt-btn-primary pt-btn-large"
          onClick={createOrder} 
          disabled={loading || !authToken || !rideId}
        >
          {loading ? '⏳ Creating...' : '🚀 Create Payment Order'}
        </button>
      </div>

      {/* Step 2: Order Created */}
      {orderData && (
        <div className="pt-step-card pt-step-card-success">
          <h2 className="pt-step-title">
            <span className="pt-step-number">2</span>
            ✅ Order Created Successfully
          </h2>
          
          <div className="pt-order-details">
            <h3 className="pt-subtitle">Order Details:</h3>
            <div className="pt-details-grid">
              <div className="pt-detail-item">
                <span className="pt-detail-label">Order ID:</span>
                <span className="pt-detail-value pt-order-id">{orderData.orderId}</span>
              </div>
              <div className="pt-detail-item">
                <span className="pt-detail-label">Amount:</span>
                <span className="pt-detail-value">₹{orderData.amount / 100}</span>
              </div>
              <div className="pt-detail-item">
                <span className="pt-detail-label">Currency:</span>
                <span className="pt-detail-value">{orderData.currency}</span>
              </div>
              <div className="pt-detail-item">
                <span className="pt-detail-label">Key ID:</span>
                <span className="pt-detail-value">{orderData.keyId}</span>
              </div>
            </div>
          </div>

          {/* Payment Method Selection */}
          <div className="pt-payment-method">
            <h3 className="pt-subtitle">💳 Payment Method</h3>
            <div className="pt-method-buttons">
              <button 
                className={`pt-method-btn ${paymentMethod === 'upi' ? 'active' : ''}`}
                onClick={() => setPaymentMethod('upi')}
              >
                📱 UPI
              </button>
              <button 
                className={`pt-method-btn ${paymentMethod === 'card' ? 'active' : ''}`}
                onClick={() => setPaymentMethod('card')}
              >
                💳 Card
              </button>
            </div>
          </div>

          {paymentMethod === 'upi' && (
            <div className="pt-upi-section">
              <h3 className="pt-subtitle">📱 UPI Payment</h3>
              <div className="pt-upi-demo">
                <div className="pt-qr-placeholder">
                  <div className="pt-qr-code">
                    <span>📱</span>
                    <span>UPI QR Code</span>
                    <small>(Demo)</small>
                  </div>
                </div>
                <div className="pt-upi-details">
                  <p><strong>UPI ID:</strong> merchant@razorpay</p>
                  <p><strong>Amount:</strong> ₹{orderData.amount / 100}</p>
                  <p><strong>Order:</strong> {orderData.orderId}</p>
                </div>
              </div>
            </div>
          )}

          <div className="pt-verification-form">
            <h3 className="pt-subtitle">🔐 Payment Verification</h3>
            
            <div className="pt-input-group">
              <label className="pt-label">Payment ID (from Razorpay):</label>
              <input
                className="pt-input"
                type="text"
                value={manualPayment.paymentId}
                onChange={(e) => setManualPayment({...manualPayment, paymentId: e.target.value})}
                placeholder="pay_upi_123456789"
              />
            </div>

            <div className="pt-input-group">
              <label className="pt-label">Order ID:</label>
              <input
                className="pt-input"
                type="text"
                value={manualPayment.orderId}
                onChange={(e) => setManualPayment({...manualPayment, orderId: e.target.value})}
                placeholder="order_test_123456789"
                readOnly
              />
            </div>

            <div className="pt-input-group">
              <label className="pt-label">Signature:</label>
              <input
                className="pt-input"
                type="text"
                value={manualPayment.signature}
                onChange={(e) => setManualPayment({...manualPayment, signature: e.target.value})}
                placeholder="razorpay_signature_here"
              />
            </div>

            <div className="pt-signature-info">
              <p><strong>Expected Signature Format:</strong></p>
              <code className="pt-code">
                HMAC_SHA256(order_id + "|" + payment_id, key_secret)
              </code>
            </div>

            <div className="pt-button-group">
              {paymentMethod === 'upi' && (
                <button 
                  className="pt-btn pt-btn-success"
                  onClick={simulateUPIPayment}
                >
                  📱 Simulate UPI Payment
                </button>
              )}
              
              <button 
                className="pt-btn pt-btn-secondary"
                onClick={() => setManualPayment({
                  paymentId: sampleTestData.paymentId,
                  orderId: orderData.orderId,
                  signature: sampleTestData.signature
                })}
              >
                🔧 Fill Test Data
              </button>

              <button 
                className="pt-btn pt-btn-primary"
                onClick={verifyPayment} 
                disabled={loading}
              >
                {loading ? '⏳ Verifying...' : '✅ Verify Payment'}
              </button>
            </div>
          </div>

          {upiDetails.transactionId && (
            <div className="pt-upi-transaction">
              <h4>UPI Transaction Details:</h4>
              <p><strong>Transaction ID:</strong> {upiDetails.transactionId}</p>
              <p><strong>VPA:</strong> {upiDetails.vpa}</p>
              <p><strong>Status:</strong> Pending Verification</p>
            </div>
          )}
        </div>
      )}

      {/* Step 3: Payment Result */}
      {paymentResult && (
        <div className={`pt-step-card ${paymentResult.success ? 'pt-step-card-success' : 'pt-step-card-error'}`}>
          <h2 className="pt-step-title">
            <span className="pt-step-number">3</span>
            Payment Result
          </h2>
          
          <div className="pt-result-message">
            {paymentResult.success ? '✅' : '❌'} {paymentResult.message}
          </div>
          
          {verificationData && (
            <div className="pt-verification-details">
              <h3 className="pt-subtitle">Verification Details:</h3>
              <pre className="pt-code-block">{JSON.stringify(verificationData, null, 2)}</pre>
            </div>
          )}

          <div className="pt-button-group">
            <button onClick={checkStatus} className="pt-btn pt-btn-secondary">
              🔄 Check Latest Status
            </button>
            <button onClick={processRefund} className="pt-btn pt-btn-warning">
              ↩️ Process Refund
            </button>
          </div>
        </div>
      )}

      {/* Webhook Testing Section */}
      {orderData && (
        <div className="pt-step-card">
          <h2 className="pt-step-title">
            <span className="pt-step-number">🔔</span>
            Webhook Testing
          </h2>
          
          <div className="pt-webhook-form">
            <div className="pt-input-group">
              <label className="pt-label">Webhook Event:</label>
              <select 
                className="pt-select"
                value={webhookPayload.event}
                onChange={(e) => setWebhookPayload({...webhookPayload, event: e.target.value})}
              >
                <option value="payment.captured">payment.captured (Success)</option>
                <option value="payment.failed">payment.failed (Failure)</option>
                <option value="order.paid">order.paid</option>
                <option value="refund.processed">refund.processed</option>
              </select>
            </div>

            <div className="pt-input-group">
              <label className="pt-label">Payment ID:</label>
              <input
                className="pt-input"
                type="text"
                value={webhookPayload.paymentId}
                onChange={(e) => setWebhookPayload({...webhookPayload, paymentId: e.target.value})}
                placeholder="pay_webhook_123456789"
              />
            </div>

            <button 
              className="pt-btn pt-btn-primary"
              onClick={testWebhook} 
              disabled={loading}
            >
              {loading ? '⏳ Sending...' : '📨 Send Test Webhook'}
            </button>
          </div>

          {webhookResponse && (
            <div className="pt-webhook-response">
              <h4 className="pt-subtitle">Webhook Response:</h4>
              <div className={`pt-status-badge ${webhookResponse.status === 200 ? 'pt-status-success' : 'pt-status-error'}`}>
                Status: {webhookResponse.status}
              </div>
              <pre className="pt-code-block">
                {JSON.stringify(webhookResponse.data, null, 2)}
              </pre>
            </div>
          )}
        </div>
      )}

      {/* Refund Data */}
      {refundData && (
        <div className="pt-step-card">
          <h2 className="pt-step-title">↩️ Refund Details</h2>
          <pre className="pt-code-block">{JSON.stringify(refundData, null, 2)}</pre>
        </div>
      )}

      {/* Payment History */}
      {paymentHistory.length > 0 && (
        <div className="pt-history-card">
          <div className="pt-history-header">
            <h3 className="pt-subtitle">📜 Payment History (Last 20)</h3>
            <button onClick={clearHistory} className="pt-btn pt-btn-small pt-btn-danger">
              Clear History
            </button>
          </div>
          <div className="pt-history-list">
            {paymentHistory.map((item) => (
              <div key={item.id} className="pt-history-item">
                <div className="pt-history-time">{new Date(item.timestamp).toLocaleTimeString()}</div>
                <div className={`pt-history-action pt-action-${item.status}`}>
                  {item.action}
                </div>
                <div className="pt-history-order">{item.orderId}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Quick Test Guide */}
      <div className="pt-guide-card">
        <h3 className="pt-guide-title">📝 Complete Test Flow Guide</h3>
        
        <div className="pt-guide-steps">
          <div className="pt-guide-step">
            <h4>Step 1: Create Order</h4>
            <ol>
              <li>Enter your JWT token</li>
              <li>Use Ride ID: <strong>RID02360983578</strong></li>
              <li>Click "Create Payment Order"</li>
            </ol>
          </div>

          <div className="pt-guide-step">
            <h4>Step 2: UPI Payment</h4>
            <ol>
              <li>Click "Simulate UPI Payment"</li>
              <li>Payment ID auto-generated</li>
              <li>Signature auto-generated</li>
              <li>Click "Verify Payment"</li>
            </ol>
          </div>

          <div className="pt-guide-step">
            <h4>Step 3: Verify</h4>
            <ol>
              <li>Check payment status</li>
              <li>Test webhook events</li>
              <li>Process refund if needed</li>
            </ol>
          </div>
        </div>

        <h4 className="pt-subtitle">Your Current Order:</h4>
        <div className="pt-current-order">
          <p><strong>Order ID:</strong> order_ST1VTP3zhprrC0</p>
          <p><strong>Amount:</strong> ₹175.00</p>
          <p><strong>Ride ID:</strong> RID02360983578</p>
          <p><strong>Key Secret:</strong> OZdye2d48zaLY1gSko96eJsX</p>
        </div>

        <h4 className="pt-subtitle">UPI Test Details:</h4>
        <div className="pt-test-cards">
          <div className="pt-card-info">
            <span className="pt-card-type">✅ Success VPA:</span>
            <code>success@razorpay</code>
          </div>
          <div className="pt-card-info">
            <span className="pt-card-type">❌ Failure VPA:</span>
            <code>failure@razorpay</code>
          </div>
          <div className="pt-card-info">
            <span className="pt-card-type">📱 UPI Apps:</span>
            <code>Google Pay, PhonePe, Paytm</code>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PaymentTester;