import React, { useState, useMemo, useEffect, useCallback } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Button,
  IconButton,
  Avatar,
  Chip,
  Switch,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Grid,
  ToggleButton,
  ToggleButtonGroup,
  TextField,
  MenuItem,
  FormControl,
  InputLabel,
  Select,
  Tooltip,
  Divider,
  FormControlLabel,
  Snackbar,
  Alert,
  CircularProgress,
  Stack,
} from '@mui/material';
import {
  GridView as GridViewIcon,
  ViewList as ViewListIcon,
  LocalShipping as VehicleIcon,
  Star as StarIcon,
  Visibility as VisibilityIcon,
  Close as CloseIcon,
  Phone as PhoneIcon,
  Email as EmailIcon,
  CheckCircle as CheckCircleIcon,
  Pending as PendingIcon,
  LocalTaxi as TaxiIcon,
  Refresh as RefreshIcon,
  Warning as WarningIcon,
} from '@mui/icons-material';
import axios from 'axios';

// API configuration
const API_BASE_URL ='http://localhost:5000/api';
const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Add token to requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('AdminToken');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

const DriverStatus = () => {
  const [viewMode, setViewMode] = useState('grid');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [verificationFilter, setVerificationFilter] = useState('all');
  const [detailsDialogOpen, setDetailsDialogOpen] = useState(false);
  const [selectedDriver, setSelectedDriver] = useState(null);
  const [drivers, setDrivers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 12,
    total: 0,
    pages: 0,
  });

  // Fetch drivers from API
  const fetchDrivers = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      
      const params = {
        page: pagination.page,
        limit: pagination.limit,
        ...(statusFilter !== 'all' && { status: statusFilter }),
        ...(verificationFilter !== 'all' && { verificationStatus: verificationFilter }),
      };
      
      const response = await api.get('/drivers', { params });
      
      if (response.data.success) {
        // Transform API data to match component format
        const transformedDrivers = response.data.data.map(driver => ({
          id: driver._id,
          name: driver.name,
          avatar: driver.name.split(' ').map(n => n[0]).join('').toUpperCase(),
          phone: driver.phone,
          email: driver.email,
          status: driver.isOnline ? 'online' : (driver.isAvailable ? 'busy' : 'offline'),
          isActive: driver.isActive,
          verificationStatus: driver.verificationStatus,
          vehicleType: driver.vehicleType,
          vehicleNumber: driver.vehicleNumber,
          rating: driver.rating || 4.5,
          totalRides: driver.totalTrips || 0,
          earnings: driver.totalEarnings || 0,
          location: driver.location || 'Not specified',
          joinedDate: driver.createdAt ? new Date(driver.createdAt).toLocaleDateString() : 'N/A',
          documents: driver.documents || {
            license: false,
            insurance: false,
            rc: false,
            pan: false,
          },
          recentTrips: driver.recentTrips || [],
          isOnline: driver.isOnline,
          isAvailable: driver.isAvailable,
          isBlocked: driver.isBlocked,
        }));
        
        setDrivers(transformedDrivers);
        setPagination(prev => ({
          ...prev,
          total: response.data.pagination?.total || transformedDrivers.length,
          pages: response.data.pagination?.pages || 1,
        }));
      }
    } catch (err) {
      console.error('Error fetching drivers:', err);
      setError(err.response?.data?.message || 'Failed to fetch drivers');
      showSnackbar('Failed to fetch drivers', 'error');
    } finally {
      setLoading(false);
    }
  }, [pagination.page, pagination.limit, statusFilter, verificationFilter]);

  // Update driver status
  const updateDriverStatus = async (driverId, updates) => {
    try {
      const response = await api.patch(`/drivers/${driverId}`, updates);
      if (response.data.success) {
        // Update local state
        setDrivers(prevDrivers =>
          prevDrivers.map(driver =>
            driver.id === driverId
              ? {
                  ...driver,
                  ...updates,
                  status: updates.isOnline ? 'online' : (updates.isAvailable ? 'busy' : 'offline'),
                }
              : driver
          )
        );
        showSnackbar('Driver status updated successfully', 'success');
        return true;
      }
    } catch (err) {
      console.error('Error updating driver:', err);
      showSnackbar(err.response?.data?.message || 'Failed to update driver', 'error');
      return false;
    }
  };

  // Toggle driver active status
  const toggleDriverActive = async (driverId, isOnline) => {
    try {
      const response = await api.patch(`/drivers/${driverId}/active`);
      if (response.data.success) {
        setDrivers(prevDrivers =>
          prevDrivers.map(driver =>
            driver.id === driverId
              ? { ...driver, isOnline: !driver.isOnline, status: !driver.isOnline ? 'online' : 'offline' }
              : driver
          )
        );
        showSnackbar(`Driver is now ${!isOnline ? 'online' : 'offline'}`, 'success');
        return true;
      }
    } catch (err) {
      console.error('Error toggling driver active:', err);
      showSnackbar(err.response?.data?.message || 'Failed to toggle driver status', 'error');
      return false;
    }
  };

  // Toggle driver block status
  const toggleBlockDriver = async (driverId, isBlocked) => {
    try {
      const response = await api.patch(`/drivers/${driverId}/toggle-block`);
      if (response.data.success) {
        setDrivers(prevDrivers =>
          prevDrivers.map(driver =>
            driver.id === driverId
              ? { ...driver, isBlocked: !driver.isBlocked }
              : driver
          )
        );
        showSnackbar(`Driver ${!isBlocked ? 'blocked' : 'unblocked'} successfully`, 'success');
        return true;
      }
    } catch (err) {
      console.error('Error toggling driver block:', err);
      showSnackbar(err.response?.data?.message || 'Failed to toggle driver block', 'error');
      return false;
    }
  };

  // Verify driver
  const verifyDriver = async (driverId) => {
    try {
      const response = await api.post(`/drivers/${driverId}/verify`);
      if (response.data.success) {
        setDrivers(prevDrivers =>
          prevDrivers.map(driver =>
            driver.id === driverId
              ? { ...driver, verificationStatus: 'verified' }
              : driver
          )
        );
        showSnackbar('Driver verified successfully', 'success');
        return true;
      }
    } catch (err) {
      console.error('Error verifying driver:', err);
      showSnackbar(err.response?.data?.message || 'Failed to verify driver', 'error');
      return false;
    }
  };

  // Reject driver
  const rejectDriver = async (driverId, reason) => {
    try {
      const response = await api.post(`/drivers/${driverId}/reject`, { reason });
      if (response.data.success) {
        setDrivers(prevDrivers =>
          prevDrivers.map(driver =>
            driver.id === driverId
              ? { ...driver, verificationStatus: 'rejected' }
              : driver
          )
        );
        showSnackbar('Driver verification rejected', 'success');
        return true;
      }
    } catch (err) {
      console.error('Error rejecting driver:', err);
      showSnackbar(err.response?.data?.message || 'Failed to reject driver', 'error');
      return false;
    }
  };

  // Update driver documents
  const updateDriverDocuments = async (driverId, documents) => {
    try {
      const response = await api.patch(`/drivers/${driverId}/documents`, { documents });
      if (response.data.success) {
        setDrivers(prevDrivers =>
          prevDrivers.map(driver =>
            driver.id === driverId
              ? { ...driver, documents }
              : driver
          )
        );
        showSnackbar('Documents updated successfully', 'success');
        return true;
      }
    } catch (err) {
      console.error('Error updating documents:', err);
      showSnackbar(err.response?.data?.message || 'Failed to update documents', 'error');
      return false;
    }
  };

  // Show snackbar notification
  const showSnackbar = (message, severity = 'success') => {
    setSnackbar({ open: true, message, severity });
  };

  // Handle driver status toggle (active/inactive)
  const handleActiveToggle = async (driverId, currentActive, event) => {
    event.stopPropagation();
    await toggleDriverActive(driverId, currentActive);
  };

  // Handle driver block toggle
  const handleBlockToggle = async (driverId, isBlocked, event) => {
    event.stopPropagation();
    await toggleBlockDriver(driverId, isBlocked);
  };

  // Handle verification toggle
  const handleVerificationToggle = async (driverId, currentStatus, event) => {
    event.stopPropagation();
    if (currentStatus === 'verified') {
      await rejectDriver(driverId, 'Manually rejected by admin');
    } else {
      await verifyDriver(driverId);
    }
  };

  // Filter logic
  const filteredDrivers = useMemo(() => {
    return drivers.filter(driver => {
      if (searchQuery && !driver.name.toLowerCase().includes(searchQuery.toLowerCase()) && 
          !driver.vehicleNumber.toLowerCase().includes(searchQuery.toLowerCase())) return false;
      if (statusFilter !== 'all' && driver.status !== statusFilter) return false;
      if (verificationFilter !== 'all' && driver.verificationStatus !== verificationFilter) return false;
      return true;
    });
  }, [drivers, searchQuery, statusFilter, verificationFilter]);

  // Statistics
  const stats = useMemo(() => {
    const total = drivers.length;
    const online = drivers.filter(d => d.status === 'online').length;
    const available = drivers.filter(d => d.status === 'online' && d.isActive).length;
    const busy = drivers.filter(d => d.status === 'busy').length;
    const offline = drivers.filter(d => d.status === 'offline').length;
    const verified = drivers.filter(d => d.verificationStatus === 'verified').length;
    const pending = drivers.filter(d => d.verificationStatus === 'pending' || d.verificationStatus === 'under_review').length;
    return { total, online, available, busy, offline, verified, pending };
  }, [drivers]);

  const handleViewModeChange = (event, newMode) => {
    if (newMode !== null) setViewMode(newMode);
  };

  const openDriverDetails = (driver) => {
    setSelectedDriver(driver);
    setDetailsDialogOpen(true);
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'online': return '#4CAF50';
      case 'busy': return '#FF9800';
      case 'offline': return '#9E9E9E';
      default: return '#9E9E9E';
    }
  };

  const getVehicleIcon = (vehicleType) => {
    if (vehicleType?.includes('Tata') || vehicleType?.includes('Pickup')) 
      return <TaxiIcon sx={{ fontSize: 16 }} />;
    if (vehicleType?.includes('Eicher') || vehicleType?.includes('Leyland') || 
        vehicleType?.includes('Benz') || vehicleType?.includes('LPT')) 
      return <></>;
    return <VehicleIcon sx={{ fontSize: 16 }} />;
  };

  // Initial load and refetch on filter/pagination change
  useEffect(() => {
    fetchDrivers();
  }, [fetchDrivers]);

  const StatChip = ({ label, value, color }) => (
    <Box sx={{ 
      display: 'flex', 
      alignItems: 'center', 
      gap: 0.5, 
      px: 1.5, 
      py: 0.5, 
      borderRadius: 1, 
      bgcolor: `${color}15`,
      border: `1px solid ${color}30`
    }}>
      <Box sx={{ width: 8, height: 8, borderRadius: '50%', bgcolor: color }} />
      <Typography variant="caption" sx={{ fontWeight: 600, color }}>
        {label}: {value}
      </Typography>
    </Box>
  );

  const renderGridView = () => (
    <Grid container spacing={1.5}>
      {filteredDrivers.map((driver) => (
        <Grid item xs={12} sm={6} md={4} lg={3} key={driver.id}>
          <Card 
            onClick={() => openDriverDetails(driver)}
            sx={{ 
              p: 1.5,
              borderRadius: 1,
              border: driver.isBlocked ? '1px solid #f44336' : '1px solid rgba(0,0,0,0.1)',
              boxShadow: 'none',
              cursor: 'pointer',
              transition: 'all 0.2s ease',
              '&:hover': { borderColor: '#FFB300', bgcolor: 'rgba(255,179,0,0.02)' },
              opacity: driver.isBlocked ? 0.7 : 1,
            }}
          >
            {driver.isBlocked && (
              <Chip 
                icon={<WarningIcon sx={{ fontSize: 12 }} />}
                label="Blocked" 
                size="small" 
                color="error"
                sx={{ position: 'absolute', top: 8, right: 8, height: 20, fontSize: '0.65rem' }}
              />
            )}
            
            {/* Row 1: Avatar + Name + Online dot */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
              <Avatar sx={{ width: 40, height: 40, bgcolor: '#FFB300', fontSize: '0.875rem', fontWeight: 700 }}>
                {driver.avatar}
              </Avatar>
              <Box sx={{ flex: 1, minWidth: 0 }}>
                <Typography variant="body2" sx={{ fontWeight: 700, fontSize: '0.875rem', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {driver.name}
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                  <Box sx={{ 
                    width: 8, 
                    height: 8, 
                    borderRadius: '50%', 
                    bgcolor: getStatusColor(driver.status),
                    animation: driver.status === 'online' ? 'pulse 2s infinite' : 'none',
                    '@keyframes pulse': {
                      '0%': { boxShadow: '0 0 0 0 rgba(76, 175, 80, 0.7)' },
                      '70%': { boxShadow: '0 0 0 6px rgba(76, 175, 80, 0)' },
                      '100%': { boxShadow: '0 0 0 0 rgba(76, 175, 80, 0)' },
                    }
                  }} />
                  <Typography variant="caption" sx={{ color: getStatusColor(driver.status), fontWeight: 600, textTransform: 'capitalize' }}>
                    {driver.status}
                  </Typography>
                </Box>
              </Box>
            </Box>

            {/* Row 2: Vehicle number + Type icon */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mb: 1, color: 'text.secondary' }}>
              {getVehicleIcon(driver.vehicleType)}
              <Typography variant="caption" sx={{ fontWeight: 500 }}>
                {driver.vehicleNumber}
              </Typography>
              <Typography variant="caption" sx={{ color: 'text.disabled' }}>•</Typography>
              <Typography variant="caption" sx={{ fontSize: '0.7rem' }}>
                {driver.vehicleType}
              </Typography>
            </Box>

            {/* Row 3: Rating + Rides */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 1.5 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.25 }}>
                <StarIcon sx={{ fontSize: 14, color: '#FFB300' }} />
                <Typography variant="caption" sx={{ fontWeight: 700 }}>{driver.rating}★</Typography>
              </Box>
              <Typography variant="caption" color="text.secondary">
                Rides: {driver.totalRides}
              </Typography>
            </Box>

            {/* Row 4: Status toggle + Verify badge */}
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <FormControlLabel
                control={
                  <Switch
                    checked={driver.isActive && !driver.isBlocked}
                    onChange={(e) => handleActiveToggle(driver.id, driver.isActive, e)}
                    size="small"
                    disabled={driver.isBlocked}
                    sx={{
                      '& .MuiSwitch-switchBase.Mui-checked': { color: '#FFB300' },
                      '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': { backgroundColor: '#FFB300' },
                    }}
                  />
                }
                label={
                  <Typography variant="caption" sx={{ fontSize: '0.7rem', color: 'text.secondary' }}>
                    Active
                  </Typography>
                }
                sx={{ m: 0, '& .MuiFormControlLabel-label': { ml: -0.5 } }}
              />
              {driver.verificationStatus === 'verified' ? (
                <Chip 
                  icon={<CheckCircleIcon sx={{ fontSize: 12 }} />} 
                  label="Verified" 
                  size="small" 
                  sx={{ 
                    height: 20, 
                    fontSize: '0.65rem', 
                    bgcolor: 'rgba(46, 125, 50, 0.1)', 
                    color: '#2E7D32',
                    '& .MuiChip-icon': { color: '#2E7D32' }
                  }} 
                />
              ) : driver.verificationStatus === 'rejected' ? (
                <Chip 
                  icon={<CloseIcon sx={{ fontSize: 12 }} />} 
                  label="Rejected" 
                  size="small" 
                  sx={{ 
                    height: 20, 
                    fontSize: '0.65rem', 
                    bgcolor: 'rgba(244, 67, 54, 0.1)', 
                    color: '#F44336',
                    '& .MuiChip-icon': { color: '#F44336' }
                  }} 
                />
              ) : (
                <Chip 
                  icon={<PendingIcon sx={{ fontSize: 12 }} />} 
                  label="Pending" 
                  size="small" 
                  sx={{ 
                    height: 20, 
                    fontSize: '0.65rem', 
                    bgcolor: 'rgba(255, 152, 0, 0.1)', 
                    color: '#ED6C02',
                    '& .MuiChip-icon': { color: '#ED6C02' }
                  }} 
                />
              )}
            </Box>
          </Card>
        </Grid>
      ))}
    </Grid>
  );

  const renderListView = () => (
    <TableContainer component={Paper} sx={{ borderRadius: 1, boxShadow: 'none', border: '1px solid rgba(0,0,0,0.1)' }}>
      <Table size="small">
        <TableHead>
          <TableRow sx={{ bgcolor: 'rgba(255, 179, 0, 0.05)' }}>
            <TableCell sx={{ py: 1, fontWeight: 700, fontSize: '0.75rem' }}>Driver</TableCell>
            <TableCell sx={{ py: 1, fontWeight: 700, fontSize: '0.75rem' }}>Vehicle</TableCell>
            <TableCell sx={{ py: 1, fontWeight: 700, fontSize: '0.75rem' }}>Status</TableCell>
            <TableCell sx={{ py: 1, fontWeight: 700, fontSize: '0.75rem' }}>Rating</TableCell>
            <TableCell sx={{ py: 1, fontWeight: 700, fontSize: '0.75rem' }}>Rides</TableCell>
            <TableCell sx={{ py: 1, fontWeight: 700, fontSize: '0.75rem' }}>Active</TableCell>
            <TableCell sx={{ py: 1, fontWeight: 700, fontSize: '0.75rem' }}>Blocked</TableCell>
            <TableCell align="center" sx={{ py: 1, fontWeight: 700, fontSize: '0.75rem' }}>Action</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {filteredDrivers.map((driver) => (
            <TableRow 
              key={driver.id} 
              hover 
              sx={{ cursor: 'pointer', bgcolor: driver.isBlocked ? 'rgba(244, 67, 54, 0.05)' : 'inherit' }} 
              onClick={() => openDriverDetails(driver)}
            >
              <TableCell sx={{ py: 1 }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                  <Box sx={{ position: 'relative' }}>
                    <Avatar sx={{ width: 32, height: 32, bgcolor: '#FFB300', fontSize: '0.75rem', fontWeight: 700 }}>
                      {driver.avatar}
                    </Avatar>
                    <Box
                      sx={{
                        position: 'absolute',
                        bottom: 0,
                        right: 0,
                        width: 10,
                        height: 10,
                        borderRadius: '50%',
                        bgcolor: getStatusColor(driver.status),
                        border: '2px solid white',
                      }}
                    />
                  </Box>
                  <Box>
                    <Typography variant="body2" sx={{ fontWeight: 600, fontSize: '0.8rem' }}>{driver.name}</Typography>
                    {driver.verificationStatus === 'verified' ? (
                      <Chip 
                        icon={<CheckCircleIcon sx={{ fontSize: 10 }} />} 
                        label="Verified" 
                        size="small" 
                        sx={{ 
                          height: 16, 
                          fontSize: '0.6rem', 
                          bgcolor: 'rgba(46, 125, 50, 0.1)', 
                          color: '#2E7D32',
                          '& .MuiChip-icon': { color: '#2E7D32', ml: '2px' }
                        }} 
                      />
                    ) : (
                      <Chip 
                        icon={<PendingIcon sx={{ fontSize: 10 }} />} 
                        label="Pending" 
                        size="small" 
                        sx={{ 
                          height: 16, 
                          fontSize: '0.6rem', 
                          bgcolor: 'rgba(255, 152, 0, 0.1)', 
                          color: '#ED6C02',
                          '& .MuiChip-icon': { color: '#ED6C02', ml: '2px' }
                        }} 
                      />
                    )}
                  </Box>
                </Box>
              </TableCell>
              <TableCell sx={{ py: 1 }}>
                <Typography variant="caption" sx={{ fontWeight: 600 }}>{driver.vehicleNumber}</Typography>
                <Typography variant="caption" color="text.secondary" display="block">{driver.vehicleType}</Typography>
              </TableCell>
              <TableCell sx={{ py: 1 }}>
                <Chip
                  label={driver.status}
                  size="small"
                  sx={{
                    height: 20,
                    fontSize: '0.65rem',
                    bgcolor: `${getStatusColor(driver.status)}15`,
                    color: getStatusColor(driver.status),
                    fontWeight: 600,
                    textTransform: 'capitalize'
                  }}
                />
              </TableCell>
              <TableCell sx={{ py: 1 }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                  <StarIcon sx={{ fontSize: 14, color: '#FFB300' }} />
                  <Typography variant="body2" sx={{ fontWeight: 700, fontSize: '0.8rem' }}>{driver.rating}</Typography>
                </Box>
              </TableCell>
              <TableCell sx={{ py: 1 }}>
                <Typography variant="body2" sx={{ fontSize: '0.8rem' }}>{driver.totalRides}</Typography>
              </TableCell>
              <TableCell sx={{ py: 1 }}>
                <Switch
                  checked={driver.isActive && !driver.isBlocked}
                  onChange={(e) => handleActiveToggle(driver.id, driver.isActive, e)}
                  size="small"
                  disabled={driver.isBlocked}
                  sx={{
                    '& .MuiSwitch-switchBase.Mui-checked': { color: '#FFB300' },
                    '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': { backgroundColor: '#FFB300' },
                  }}
                />
              </TableCell>
              <TableCell sx={{ py: 1 }}>
                <Switch
                  checked={driver.isBlocked}
                  onChange={(e) => handleBlockToggle(driver.id, driver.isBlocked, e)}
                  size="small"
                  color="error"
                  sx={{
                    '& .MuiSwitch-switchBase.Mui-checked': { color: '#F44336' },
                    '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': { backgroundColor: '#F44336' },
                  }}
                />
              </TableCell>
              <TableCell align="center" sx={{ py: 1 }}>
                <Tooltip title="View Details">
                  <IconButton size="small" sx={{ color: '#FFB300' }}>
                    <VisibilityIcon sx={{ fontSize: 18 }} />
                  </IconButton>
                </Tooltip>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );

  const DriverDetailsDialog = () => {
    if (!selectedDriver) return null;

    const handleDocumentToggle = (docName) => {
      const updatedDocuments = {
        ...selectedDriver.documents,
        [docName]: !selectedDriver.documents[docName],
      };
      updateDriverDocuments(selectedDriver.id, updatedDocuments);
      setSelectedDriver({ ...selectedDriver, documents: updatedDocuments });
    };

    const handleSaveChanges = async () => {
      await updateDriverStatus(selectedDriver.id, {
        isActive: selectedDriver.isActive,
        isOnline: selectedDriver.status === 'online',
        isAvailable: selectedDriver.status === 'busy',
      });
      setDetailsDialogOpen(false);
    };

    return (
      <Dialog open={detailsDialogOpen} onClose={() => setDetailsDialogOpen(false)} maxWidth="md" fullWidth PaperProps={{ sx: { borderRadius: 1 } }}>
        <DialogTitle sx={{ pb: 1, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
            <Box sx={{ position: 'relative' }}>
              <Avatar sx={{ width: 56, height: 56, bgcolor: '#FFB300', fontSize: '1.25rem', fontWeight: 700 }}>
                {selectedDriver.avatar}
              </Avatar>
              <Box
                sx={{
                  position: 'absolute',
                  bottom: 2,
                  right: 2,
                  width: 14,
                  height: 14,
                  borderRadius: '50%',
                  bgcolor: getStatusColor(selectedDriver.status),
                  border: '2px solid white',
                }}
              />
            </Box>
            <Box>
              <Typography variant="h6" sx={{ fontWeight: 700, fontSize: '1.1rem' }}>{selectedDriver.name}</Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                <Typography variant="caption" sx={{ color: getStatusColor(selectedDriver.status), fontWeight: 600, textTransform: 'capitalize' }}>
                  {selectedDriver.status}
                </Typography>
                {selectedDriver.verificationStatus === 'verified' ? (
                  <Chip 
                    icon={<CheckCircleIcon sx={{ fontSize: 12 }} />} 
                    label="Verified" 
                    size="small" 
                    sx={{ 
                      height: 20, 
                      fontSize: '0.65rem', 
                      bgcolor: 'rgba(46, 125, 50, 0.1)', 
                      color: '#2E7D32',
                      '& .MuiChip-icon': { color: '#2E7D32' }
                    }} 
                  />
                ) : (
                  <Chip 
                    icon={<PendingIcon sx={{ fontSize: 12 }} />} 
                    label="Pending" 
                    size="small" 
                    sx={{ 
                      height: 20, 
                      fontSize: '0.65rem', 
                      bgcolor: 'rgba(255, 152, 0, 0.1)', 
                      color: '#ED6C02',
                      '& .MuiChip-icon': { color: '#ED6C02' }
                    }} 
                  />
                )}
              </Box>
            </Box>
          </Box>
          <IconButton onClick={() => setDetailsDialogOpen(false)} size="small">
            <CloseIcon />
          </IconButton>
        </DialogTitle>

        <DialogContent sx={{ pt: 2 }}>
          {/* Info Grid */}
          <Grid container spacing={1} sx={{ mb: 3 }}>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ p: 1, bgcolor: 'rgba(0,0,0,0.02)', borderRadius: 1 }}>
                <Typography variant="caption" color="text.secondary" display="block">Phone</Typography>
                <Typography variant="body2" sx={{ fontWeight: 600, fontSize: '0.8rem' }}>{selectedDriver.phone}</Typography>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ p: 1, bgcolor: 'rgba(0,0,0,0.02)', borderRadius: 1 }}>
                <Typography variant="caption" color="text.secondary" display="block">Email</Typography>
                <Typography variant="body2" sx={{ fontWeight: 600, fontSize: '0.8rem' }}>{selectedDriver.email}</Typography>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ p: 1, bgcolor: 'rgba(0,0,0,0.02)', borderRadius: 1 }}>
                <Typography variant="caption" color="text.secondary" display="block">Vehicle</Typography>
                <Typography variant="body2" sx={{ fontWeight: 600, fontSize: '0.8rem' }}>{selectedDriver.vehicleType}</Typography>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ p: 1, bgcolor: 'rgba(0,0,0,0.02)', borderRadius: 1 }}>
                <Typography variant="caption" color="text.secondary" display="block">Vehicle No</Typography>
                <Typography variant="body2" sx={{ fontWeight: 600, fontSize: '0.8rem' }}>{selectedDriver.vehicleNumber}</Typography>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ p: 1, bgcolor: 'rgba(0,0,0,0.02)', borderRadius: 1 }}>
                <Typography variant="caption" color="text.secondary" display="block">Rating</Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                  <StarIcon sx={{ fontSize: 14, color: '#FFB300' }} />
                  <Typography variant="body2" sx={{ fontWeight: 600 }}>{selectedDriver.rating}</Typography>
                </Box>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ p: 1, bgcolor: 'rgba(0,0,0,0.02)', borderRadius: 1 }}>
                <Typography variant="caption" color="text.secondary" display="block">Total Rides</Typography>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>{selectedDriver.totalRides}</Typography>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ p: 1, bgcolor: 'rgba(0,0,0,0.02)', borderRadius: 1 }}>
                <Typography variant="caption" color="text.secondary" display="block">Earnings</Typography>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>₹{selectedDriver.earnings.toLocaleString()}</Typography>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ p: 1, bgcolor: 'rgba(0,0,0,0.02)', borderRadius: 1 }}>
                <Typography variant="caption" color="text.secondary" display="block">Joined</Typography>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>{selectedDriver.joinedDate}</Typography>
              </Box>
            </Grid>
          </Grid>

          {/* Status Controls */}
          <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1.5, fontSize: '0.85rem' }}>Status Controls</Typography>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 3, mb: 3 }}>
            <FormControlLabel
              control={
                <Switch 
                  checked={selectedDriver.status === 'online'} 
                  onChange={(e) => setSelectedDriver({ 
                    ...selectedDriver, 
                    status: e.target.checked ? 'online' : 'offline',
                    isOnline: e.target.checked,
                    isAvailable: e.target.checked
                  })}
                  size="small"
                  disabled={selectedDriver.isBlocked}
                  sx={{ '& .MuiSwitch-switchBase.Mui-checked': { color: '#4CAF50' }, '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': { backgroundColor: '#4CAF50' } }} 
                />
              }
              label={<Typography variant="caption">Online/Offline</Typography>}
            />
            <FormControlLabel
              control={
                <Switch 
                  checked={selectedDriver.isActive} 
                  onChange={(e) => setSelectedDriver({ ...selectedDriver, isActive: e.target.checked })}
                  size="small"
                  disabled={selectedDriver.isBlocked}
                  sx={{ '& .MuiSwitch-switchBase.Mui-checked': { color: '#FFB300' }, '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': { backgroundColor: '#FFB300' } }} 
                />
              }
              label={<Typography variant="caption">Active/Inactive</Typography>}
            />
            <FormControlLabel
              control={
                <Switch 
                  checked={selectedDriver.isBlocked}
                  onChange={(e) => setSelectedDriver({ ...selectedDriver, isBlocked: e.target.checked })}
                  size="small"
                  color="error"
                  sx={{ '& .MuiSwitch-switchBase.Mui-checked': { color: '#F44336' }, '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': { backgroundColor: '#F44336' } }} 
                />
              }
              label={<Typography variant="caption">Block/Unblock</Typography>}
            />
            <FormControlLabel
              control={
                <Switch 
                  checked={selectedDriver.verificationStatus === 'verified'} 
                  onChange={(e) => setSelectedDriver({ 
                    ...selectedDriver, 
                    verificationStatus: e.target.checked ? 'verified' : 'pending'
                  })}
                  size="small"
                  sx={{ '& .MuiSwitch-switchBase.Mui-checked': { color: '#2E7D32' }, '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': { backgroundColor: '#2E7D32' } }} 
                />
              }
              label={<Typography variant="caption">Verified/Pending</Typography>}
            />
          </Box>

          {/* Recent Trips */}
          {selectedDriver.recentTrips && selectedDriver.recentTrips.length > 0 && (
            <>
              <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1.5, fontSize: '0.85rem' }}>Recent Trips</Typography>
              <TableContainer component={Paper} sx={{ borderRadius: 1, boxShadow: 'none', border: '1px solid rgba(0,0,0,0.1)', mb: 3 }}>
                <Table size="small">
                  <TableHead>
                    <TableRow sx={{ bgcolor: 'rgba(0,0,0,0.02)' }}>
                      <TableCell sx={{ py: 0.75, fontWeight: 700, fontSize: '0.7rem' }}>Trip ID</TableCell>
                      <TableCell sx={{ py: 0.75, fontWeight: 700, fontSize: '0.7rem' }}>Date</TableCell>
                      <TableCell sx={{ py: 0.75, fontWeight: 700, fontSize: '0.7rem' }}>From</TableCell>
                      <TableCell sx={{ py: 0.75, fontWeight: 700, fontSize: '0.7rem' }}>To</TableCell>
                      <TableCell sx={{ py: 0.75, fontWeight: 700, fontSize: '0.7rem' }}>Amount</TableCell>
                      <TableCell sx={{ py: 0.75, fontWeight: 700, fontSize: '0.7rem' }}>Status</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {selectedDriver.recentTrips.map((trip) => (
                      <TableRow key={trip.id}>
                        <TableCell sx={{ py: 0.75, fontSize: '0.75rem' }}>{trip.id}</TableCell>
                        <TableCell sx={{ py: 0.75, fontSize: '0.75rem' }}>{trip.date}</TableCell>
                        <TableCell sx={{ py: 0.75, fontSize: '0.75rem' }}>{trip.from}</TableCell>
                        <TableCell sx={{ py: 0.75, fontSize: '0.75rem' }}>{trip.to}</TableCell>
                        <TableCell sx={{ py: 0.75, fontSize: '0.75rem' }}>₹{trip.amount}</TableCell>
                        <TableCell sx={{ py: 0.75 }}>
                          <Chip
                            label={trip.status}
                            size="small"
                            sx={{
                              height: 18,
                              fontSize: '0.6rem',
                              bgcolor: trip.status === 'Completed' ? 'rgba(46, 125, 50, 0.1)' : 'rgba(255, 152, 0, 0.1)',
                              color: trip.status === 'Completed' ? '#2E7D32' : '#ED6C02',
                              fontWeight: 600
                            }}
                          />
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            </>
          )}

          {/* Documents */}
          <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1.5, fontSize: '0.85rem' }}>Documents</Typography>
          <Grid container spacing={1}>
            {selectedDriver.documents && Object.entries(selectedDriver.documents).map(([doc, status]) => (
              <Grid item xs={6} sm={3} key={doc}>
                <Box 
                  onClick={() => handleDocumentToggle(doc)}
                  sx={{ 
                    p: 1, 
                    borderRadius: 1, 
                    border: '1px solid',
                    borderColor: status ? 'rgba(46, 125, 50, 0.3)' : 'rgba(255, 152, 0, 0.3)',
                    bgcolor: status ? 'rgba(46, 125, 50, 0.05)' : 'rgba(255, 152, 0, 0.05)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    cursor: 'pointer',
                    transition: 'all 0.2s ease',
                    '&:hover': { opacity: 0.8 }
                  }}
                >
                  <Typography variant="caption" sx={{ fontWeight: 600, textTransform: 'uppercase', fontSize: '0.7rem' }}>
                    {doc}
                  </Typography>
                  {status ? (
                    <CheckCircleIcon sx={{ color: '#2E7D32', fontSize: 16 }} />
                  ) : (
                    <PendingIcon sx={{ color: '#ED6C02', fontSize: 16 }} />
                  )}
                </Box>
              </Grid>
            ))}
          </Grid>
        </DialogContent>

        <DialogActions sx={{ px: 3, pb: 2, pt: 1 }}>
          <Button onClick={() => setDetailsDialogOpen(false)} size="small" sx={{ borderRadius: 1 }}>
            Close
          </Button>
          <Button
            variant="contained"
            size="small"
            onClick={handleSaveChanges}
            sx={{ 
              borderRadius: 1,
              bgcolor: '#FFB300',
              '&:hover': { bgcolor: '#FFA000' }
            }}
          >
            Save Changes
          </Button>
        </DialogActions>
      </Dialog>
    );
  };

  if (loading && drivers.length === 0) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
        <CircularProgress sx={{ color: '#FFB300' }} />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 2 }}>
      {/* Header with Stats */}
      <Box sx={{ mb: 2 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1.5 }}>
          <Typography variant="h6" sx={{ fontWeight: 700, fontSize: '1.1rem' }}>
            Driver Status Management
          </Typography>
          <Button
            startIcon={<RefreshIcon />}
            onClick={fetchDrivers}
            size="small"
            sx={{ borderRadius: 1, textTransform: 'none' }}
          >
            Refresh
          </Button>
        </Box>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          <StatChip label="Total" value={stats.total} color="#FFB300" />
          <StatChip label="Online" value={stats.online} color="#4CAF50" />
          <StatChip label="Available" value={stats.available} color="#2196F3" />
          <StatChip label="On Trip" value={stats.busy} color="#FF9800" />
          <StatChip label="Offline" value={stats.offline} color="#9E9E9E" />
          <StatChip label="Verified" value={stats.verified} color="#2E7D32" />
          <StatChip label="Pending" value={stats.pending} color="#ED6C02" />
        </Box>
      </Box>

      {/* Filter Bar */}
      <Card sx={{ mb: 2, borderRadius: 1, boxShadow: 'none', border: '1px solid rgba(0,0,0,0.1)' }}>
        <CardContent sx={{ p: 1.5, '&:last-child': { pb: 1.5 }, display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 1.5 }}>
          <TextField
            placeholder="Search drivers..."
            size="small"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            sx={{ 
              minWidth: 180,
              '& .MuiOutlinedInput-root': { borderRadius: 1, fontSize: '0.8rem' }
            }}
          />
          <FormControl size="small" sx={{ minWidth: 120 }}>
            <InputLabel sx={{ fontSize: '0.8rem' }}>Status</InputLabel>
            <Select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              label="Status"
              sx={{ borderRadius: 1, fontSize: '0.8rem' }}
            >
              <MenuItem value="all" sx={{ fontSize: '0.8rem' }}>All</MenuItem>
              <MenuItem value="online" sx={{ fontSize: '0.8rem' }}>Online</MenuItem>
              <MenuItem value="offline" sx={{ fontSize: '0.8rem' }}>Offline</MenuItem>
              <MenuItem value="busy" sx={{ fontSize: '0.8rem' }}>Busy</MenuItem>
            </Select>
          </FormControl>
          <FormControl size="small" sx={{ minWidth: 120 }}>
            <InputLabel sx={{ fontSize: '0.8rem' }}>Verification</InputLabel>
            <Select
              value={verificationFilter}
              onChange={(e) => setVerificationFilter(e.target.value)}
              label="Verification"
              sx={{ borderRadius: 1, fontSize: '0.8rem' }}
            >
              <MenuItem value="all" sx={{ fontSize: '0.8rem' }}>All</MenuItem>
              <MenuItem value="verified" sx={{ fontSize: '0.8rem' }}>Verified</MenuItem>
              <MenuItem value="pending" sx={{ fontSize: '0.8rem' }}>Pending</MenuItem>
              <MenuItem value="rejected" sx={{ fontSize: '0.8rem' }}>Rejected</MenuItem>
            </Select>
          </FormControl>
          <Box sx={{ flex: 1 }} />
          <ToggleButtonGroup
            value={viewMode}
            exclusive
            onChange={handleViewModeChange}
            size="small"
            sx={{
              '& .MuiToggleButton-root': {
                px: 1.5,
                py: 0.5,
                borderRadius: '4px !important',
              },
              '& .MuiToggleButton-root.Mui-selected': {
                backgroundColor: '#FFB300',
                color: 'white',
                '&:hover': { backgroundColor: '#FFA000' }
              }
            }}
          >
            <ToggleButton value="grid">
              <GridViewIcon sx={{ fontSize: 18, mr: 0.5 }} />
              <Typography variant="caption" sx={{ fontSize: '0.75rem' }}>Grid</Typography>
            </ToggleButton>
            <ToggleButton value="list">
              <ViewListIcon sx={{ fontSize: 18, mr: 0.5 }} />
              <Typography variant="caption" sx={{ fontSize: '0.75rem' }}>List</Typography>
            </ToggleButton>
          </ToggleButtonGroup>
        </CardContent>
      </Card>

      {/* Content */}
      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress sx={{ color: '#FFB300' }} />
        </Box>
      ) : error ? (
        <Paper sx={{ p: 4, textAlign: 'center', borderRadius: 1 }}>
          <Typography color="error">{error}</Typography>
          <Button onClick={fetchDrivers} sx={{ mt: 2 }} variant="outlined">
            Retry
          </Button>
        </Paper>
      ) : filteredDrivers.length === 0 ? (
        <Paper sx={{ p: 4, textAlign: 'center', borderRadius: 1 }}>
          <Typography color="text.secondary">No drivers found</Typography>
        </Paper>
      ) : viewMode === 'grid' ? renderGridView() : renderListView()}

      {/* Pagination */}
      {pagination.pages > 1 && (
        <Box sx={{ display: 'flex', justifyContent: 'center', mt: 3 }}>
          <Stack direction="row" spacing={1}>
            <Button
              disabled={pagination.page === 1}
              onClick={() => setPagination(prev => ({ ...prev, page: prev.page - 1 }))}
              size="small"
            >
              Previous
            </Button>
            <Typography variant="body2" sx={{ alignSelf: 'center' }}>
              Page {pagination.page} of {pagination.pages}
            </Typography>
            <Button
              disabled={pagination.page === pagination.pages}
              onClick={() => setPagination(prev => ({ ...prev, page: prev.page + 1 }))}
              size="small"
            >
              Next
            </Button>
          </Stack>
        </Box>
      )}

      {/* Driver Details Dialog */}
      <DriverDetailsDialog />

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert 
          onClose={() => setSnackbar({ ...snackbar, open: false })} 
          severity={snackbar.severity}
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default DriverStatus;