import React, { createContext, useContext, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import io from 'socket.io-client';

const CustomerAuthContext = createContext();

const API_URL = 'https://godelivo.com';

export const CustomerAuthProvider = ({ children }) => {
  const [customer, setCustomer] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('customerToken'));
  const [loading, setLoading] = useState(true);
  const [socket, setSocket] = useState(null);
  const navigate = useNavigate();

  // Connect to socket when authenticated
  useEffect(() => {
    if (token && customer) {
      const newSocket = io(`${API_URL}/support`);
      setSocket(newSocket);

      newSocket.on('connect', () => {
        console.log('Connected to support socket');
      });

      return () => newSocket.close();
    }
  }, [token, customer]);

  // Verify token on mount
  useEffect(() => {
    const verifyToken = async () => {
      const storedToken = localStorage.getItem('customerToken');
      
      if (!storedToken) {
        setLoading(false);
        return;
      }

      try {
        const response = await fetch(`${API_URL}/api/auth/mobile/profile`, {
          headers: {
            'Authorization': `Bearer ${storedToken}`
          }
        });

        const data = await response.json();

        if (data.success) {
          // Ensure we have the correct ID field
          const customerData = data.data;
          setCustomer({
            id: customerData._id || customerData.id, // Handle both _id and id
            _id: customerData._id || customerData.id,
            name: customerData.name,
            phone: customerData.phone,
            email: customerData.email
          });
          setToken(storedToken);
        } else {
          localStorage.removeItem('customerToken');
          setToken(null);
          setCustomer(null);
        }
      } catch (error) {
        console.error('Token verification error:', error);
        localStorage.removeItem('customerToken');
        setToken(null);
        setCustomer(null);
      } finally {
        setLoading(false);
      }
    };

    verifyToken();
  }, []);

  const login = async (phone, otp) => {
    try {
      const response = await fetch(`${API_URL}/api/auth/mobile/verify-otp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mobile: phone, otp })
      });

      const data = await response.json();

      if (!data.success) {
        return { success: false, error: data.message };
      }

      const { token, customer } = data.data;

      // Store the customer with consistent ID field
      localStorage.setItem('customerToken', token);
      setToken(token);
      setCustomer({
        id: customer._id || customer.id || customer.customer?.id,
        _id: customer._id || customer.id || customer.customer?.id,
        name: customer.name || customer.customer?.name,
        phone: customer.phone || customer.customer?.phone,
        email: customer.email || customer.customer?.email
      });

      return { success: true };
    } catch (error) {
      return { success: false, error: 'Network error' };
    }
  };

  const logout = () => {
    localStorage.removeItem('customerToken');
    setToken(null);
    setCustomer(null);
    if (socket) {
      socket.close();
    }
    toast.success('Logged out successfully');
    navigate('/mobile/login');
  };

  const value = {
    customer,
    token,
    isAuthenticated: !!token && !!customer,
    loading,
    login,
    logout,
    socket
  };

  return (
    <CustomerAuthContext.Provider value={value}>
      {children}
    </CustomerAuthContext.Provider>
  );
};

export const useCustomerAuth = () => {
  const context = useContext(CustomerAuthContext);
  if (!context) {
    throw new Error('useCustomerAuth must be used within CustomerAuthProvider');
  }
  return context;
};