import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Button,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Chip,
  Avatar,
  Grid,
  Switch,
  Divider,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  ToggleButton,
  ToggleButtonGroup,
  CircularProgress,
  Alert,
  Snackbar,
  TablePagination,
  InputAdornment,
  Tooltip,
  Paper,
  Stack
} from '@mui/material';
import {
  Search as SearchIcon,
  Visibility as VisibilityIcon,
  Block as BlockIcon,
  CheckCircle as CheckCircleIcon,
  Phone as PhoneIcon,
  Email as EmailIcon,
  LocationOn as LocationIcon,
  CalendarToday as CalendarIcon,
  AccessTime as TimeIcon,
  LocalShipping as ShippingIcon,
  AttachMoney as MoneyIcon,
  Person as PersonIcon,
  Edit as EditIcon,
  Refresh as RefreshIcon,
  People as PeopleIcon,
  TrendingUp as TrendingUpIcon,
  Star as StarIcon
} from '@mui/icons-material';
import axios from 'axios';
import { format } from 'date-fns';
import toast from 'react-hot-toast';

const API_BASE_URL = 'https://godelivo.com';

const UserStatus = () => {
  const [customers, setCustomers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filter, setFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [totalCustomers, setTotalCustomers] = useState(0);
  const [stats, setStats] = useState(null);
  
  const [viewDialogOpen, setViewDialogOpen] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [confirmDialogOpen, setConfirmDialogOpen] = useState(false);
  const [pendingStatusChange, setPendingStatusChange] = useState(null);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [editFormData, setEditFormData] = useState({ name: '', email: '', address: '' });
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

  // Fetch customers from API
  const fetchCustomers = async () => {
    setLoading(true);
    setError(null);
    try {
      const token = localStorage.getItem('AdminToken');
      const params = {
        page: page + 1,
        limit: rowsPerPage,
        sortBy: 'createdAt',
        sortOrder: 'desc'
      };
      
      if (filter !== 'all') {
        params.isBlocked = filter === 'active' ? 'false' : 'true';
      }
      
      if (searchQuery) {
        params.search = searchQuery;
      }
      
      const response = await axios.get(`${API_BASE_URL}/api/customers`, {
        headers: { Authorization: `Bearer ${token}` },
        params
      });
      
      if (response.data.success) {
        setCustomers(response.data.data);
        setTotalCustomers(response.data.pagination.total);
      }
    } catch (error) {
      console.error('Error fetching customers:', error);
      setError(error.response?.data?.message || 'Failed to fetch customers');
      toast.error('Failed to fetch customers');
    } finally {
      setLoading(false);
    }
  };

  // Fetch stats
  const fetchStats = async () => {
    try {
      const token = localStorage.getItem('AdminToken');
      const response = await axios.get(`${API_BASE_URL}/api/customers/stats`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      if (response.data.success) {
        setStats(response.data.data);
      }
    } catch (error) {
      console.error('Error fetching stats:', error);
    }
  };

  useEffect(() => {
    fetchCustomers();
    fetchStats();
  }, [page, rowsPerPage, filter, searchQuery]);

  const handleFilterChange = (event, newFilter) => {
    if (newFilter !== null) {
      setFilter(newFilter);
      setPage(0);
    }
  };

  const handleSearch = (e) => {
    setSearchQuery(e.target.value);
    setPage(0);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleToggleStatus = async (customerId) => {
    try {
      const token = localStorage.getItem('AdminToken');
      const response = await axios.patch(
        `${API_BASE_URL}/api/customers/${customerId}/toggle-block`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      
      if (response.data.success) {
        toast.success(response.data.message);
        fetchCustomers();
        fetchStats();
        setSnackbar({
          open: true,
          message: response.data.message,
          severity: 'success'
        });
      }
    } catch (error) {
      console.error('Error toggling status:', error);
      toast.error(error.response?.data?.message || 'Failed to update status');
      setSnackbar({
        open: true,
        message: error.response?.data?.message || 'Failed to update status',
        severity: 'error'
      });
    }
    setConfirmDialogOpen(false);
    setPendingStatusChange(null);
  };

  const handleViewCustomer = (customer) => {
    setSelectedCustomer(customer);
    setViewDialogOpen(true);
  };

  const handleEditCustomer = (customer) => {
    setSelectedCustomer(customer);
    setEditFormData({
      name: customer.name,
      email: customer.email || '',
      address: customer.address ? JSON.stringify(customer.address) : ''
    });
    setEditDialogOpen(true);
  };

  const handleUpdateCustomer = async () => {
    try {
      const token = localStorage.getItem('AdminToken');
      let addressObj = null;
      
      if (editFormData.address) {
        try {
          addressObj = JSON.parse(editFormData.address);
        } catch (e) {
          addressObj = { street: editFormData.address };
        }
      }
      
      const response = await axios.put(
        `${API_BASE_URL}/api/customers/${selectedCustomer._id}`,
        {
          name: editFormData.name,
          email: editFormData.email,
          address: addressObj
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      
      if (response.data.success) {
        toast.success('Customer updated successfully');
        fetchCustomers();
        setEditDialogOpen(false);
        setSnackbar({
          open: true,
          message: 'Customer updated successfully',
          severity: 'success'
        });
      }
    } catch (error) {
      console.error('Error updating customer:', error);
      toast.error(error.response?.data?.message || 'Failed to update customer');
      setSnackbar({
        open: true,
        message: error.response?.data?.message || 'Failed to update customer',
        severity: 'error'
      });
    }
  };

  const formatAddress = (address) => {
    if (!address) return 'Not provided';
    if (typeof address === 'string') return address;
    return `${address.street || ''}, ${address.city || ''}, ${address.state || ''} - ${address.pincode || ''}`.trim();
  };

  if (loading && customers.length === 0) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '400px' }}>
        <CircularProgress sx={{ color: '#FFB300' }} />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3, bgcolor: '#f5f5f5', minHeight: '100vh' }}>
      {/* Stats Cards */}
      {stats && (
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ borderRadius: 2, boxShadow: 'none', border: '1px solid #e0e0e0' }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <Box>
                    <Typography variant="caption" sx={{ color: '#9e9e9e' }}>Total Customers</Typography>
                    <Typography variant="h4" sx={{ fontWeight: 700, color: '#212121' }}>{stats.total}</Typography>
                  </Box>
                  <PeopleIcon sx={{ fontSize: 40, color: '#FFB300', opacity: 0.7 }} />
                </Box>
              </CardContent>
            </Card>
          </Grid>
          
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ borderRadius: 2, boxShadow: 'none', border: '1px solid #e0e0e0' }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <Box>
                    <Typography variant="caption" sx={{ color: '#9e9e9e' }}>Active Customers</Typography>
                    <Typography variant="h4" sx={{ fontWeight: 700, color: '#4caf50' }}>{stats.active}</Typography>
                  </Box>
                  <CheckCircleIcon sx={{ fontSize: 40, color: '#4caf50', opacity: 0.7 }} />
                </Box>
              </CardContent>
            </Card>
          </Grid>
          
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ borderRadius: 2, boxShadow: 'none', border: '1px solid #e0e0e0' }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <Box>
                    <Typography variant="caption" sx={{ color: '#9e9e9e' }}>Blocked Customers</Typography>
                    <Typography variant="h4" sx={{ fontWeight: 700, color: '#f44336' }}>{stats.blocked}</Typography>
                  </Box>
                  <BlockIcon sx={{ fontSize: 40, color: '#f44336', opacity: 0.7 }} />
                </Box>
              </CardContent>
            </Card>
          </Grid>
          
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ borderRadius: 2, boxShadow: 'none', border: '1px solid #e0e0e0' }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <Box>
                    <Typography variant="caption" sx={{ color: '#9e9e9e' }}>New This Week</Typography>
                    <Typography variant="h4" sx={{ fontWeight: 700, color: '#2196f3' }}>{stats.newThisWeek}</Typography>
                  </Box>
                  <TrendingUpIcon sx={{ fontSize: 40, color: '#2196f3', opacity: 0.7 }} />
                </Box>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {/* Header and Filters */}
      <Paper sx={{ p: 2, mb: 2, borderRadius: 2, boxShadow: 'none', border: '1px solid #e0e0e0' }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 2, mb: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 700, color: '#212121' }}>
            Customer Management
          </Typography>
          <Button
            startIcon={<RefreshIcon />}
            onClick={() => fetchCustomers()}
            size="small"
            sx={{ color: '#FFB300' }}
          >
            Refresh
          </Button>
        </Box>

        <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
          {/* <TextField
            placeholder="Search by name, email, or phone..."
            value={searchQuery}
            onChange={handleSearch}
            size="small"
            sx={{ flex: 1, minWidth: 200 }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon sx={{ color: '#9e9e9e' }} />
                </InputAdornment>
              ),
            }}
          /> */}
          
          <ToggleButtonGroup
            value={filter}
            exclusive
            onChange={handleFilterChange}
            size="small"
            sx={{ 
              '& .MuiToggleButton-root': {
                px: 2,
                py: 0.5,
                textTransform: 'none',
                fontWeight: 500,
                border: '1px solid #e0e0e0',
                '&.Mui-selected': {
                  bgcolor: '#FFB300',
                  color: '#fff',
                },
              },
            }}
          >
            <ToggleButton value="all">All</ToggleButton>
            <ToggleButton value="active">Active</ToggleButton>
            <ToggleButton value="blocked">Blocked</ToggleButton>
          </ToggleButtonGroup>
        </Box>
      </Paper>

      {/* Customer Cards Grid */}
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}
      
      <Grid container spacing={2}>
        {customers.map((customer) => (
          <Grid item xs={12} sm={6} md={4} lg={3} key={customer._id}>
            <Card 
              sx={{ 
                borderRadius: 2, 
                border: '1px solid #e0e0e0',
                boxShadow: 'none',
                transition: 'all 0.2s ease',
                '&:hover': {
                  borderColor: '#FFB300',
                  boxShadow: '0 2px 8px rgba(255, 179, 0, 0.15)',
                },
              }}
            >
              <CardContent sx={{ p: 2 }}>
                <Box sx={{ display: 'flex', alignItems: 'flex-start', mb: 1.5 }}>
                  <Avatar
                    sx={{
                      width: 48,
                      height: 48,
                      bgcolor: customer.isBlocked ? '#9e9e9e' : '#FFB300',
                      color: '#fff',
                      fontWeight: 600,
                      fontSize: 18,
                      borderRadius: 1,
                    }}
                  >
                    {customer?.name?.charAt(0)?.toUpperCase()}
                  </Avatar>
                  <Box sx={{ ml: 1.5, flex: 1 }}>
                    <Typography variant="subtitle2" sx={{ fontWeight: 700, color: '#212121', lineHeight: 1.2 }}>
                      {customer.name}
                    </Typography>
                    <Typography variant="caption" sx={{ color: '#757575', display: 'block' }}>
                      {customer.email || 'No email'}
                    </Typography>
                    <Typography variant="caption" sx={{ color: '#757575', display: 'block' }}>
                      {customer.phone}
                    </Typography>
                  </Box>
                </Box>

                <Divider sx={{ my: 1.5 }} />

                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1.5 }}>
                  <Box>
                    <Typography variant="caption" sx={{ color: '#9e9e9e', display: 'block' }}>
                      Joined
                    </Typography>
                    <Typography variant="body2" sx={{ fontWeight: 500 }}>
                      {format(new Date(customer.createdAt), 'dd MMM yyyy')}
                    </Typography>
                  </Box>
                  <Box sx={{ textAlign: 'right' }}>
                    <Typography variant="caption" sx={{ color: '#9e9e9e', display: 'block' }}>
                      Total Trips
                    </Typography>
                    <Typography variant="body2" sx={{ fontWeight: 500 }}>
                      {customer.totalTrips}
                    </Typography>
                  </Box>
                </Box>

                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Switch
                      checked={!customer.isBlocked}
                      onChange={() => {
                        setPendingStatusChange(customer._id);
                        setConfirmDialogOpen(true);
                      }}
                      size="small"
                      sx={{
                        '& .MuiSwitch-switchBase.Mui-checked': {
                          color: '#4caf50',
                        },
                        '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': {
                          bgcolor: '#4caf50',
                        },
                      }}
                    />
                    <Typography variant="caption" sx={{ fontWeight: 600, color: customer.isBlocked ? '#f44336' : '#4caf50' }}>
                      {customer.isBlocked ? 'Blocked' : 'Active'}
                    </Typography>
                  </Box>
                  <Box>
                    <Tooltip title="View Details">
                      <IconButton
                        size="small"
                        onClick={() => handleViewCustomer(customer)}
                        sx={{ color: '#FFB300' }}
                      >
                        <VisibilityIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Edit">
                      <IconButton
                        size="small"
                        onClick={() => handleEditCustomer(customer)}
                        sx={{ color: '#757575' }}
                      >
                        <EditIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {customers.length === 0 && !loading && (
        <Box sx={{ textAlign: 'center', py: 4 }}>
          <Typography variant="body2" sx={{ color: '#9e9e9e' }}>
            No customers found
          </Typography>
        </Box>
      )}

      {/* Pagination */}
      {totalCustomers > 0 && (
        <TablePagination
          component="div"
          count={totalCustomers}
          page={page}
          onPageChange={handleChangePage}
          rowsPerPage={rowsPerPage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          rowsPerPageOptions={[5, 10, 25, 50]}
          sx={{ mt: 2 }}
        />
      )}

      {/* View Customer Dialog */}
      <Dialog
        open={viewDialogOpen}
        onClose={() => setViewDialogOpen(false)}
        maxWidth="sm"
        fullWidth
        PaperProps={{ sx: { borderRadius: 2 } }}
      >
        {selectedCustomer && (
          <>
            <DialogTitle sx={{ pb: 1, bgcolor: '#FFB300', color: '#fff' }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <Avatar sx={{ bgcolor: '#fff', color: '#FFB300', width: 48, height: 48 }}>
                  {selectedCustomer?.name?.charAt(0)?.toUpperCase()}
                </Avatar>
                <Box>
                  <Typography variant="h6" sx={{ fontWeight: 700 }}>
                    {selectedCustomer.name}
                  </Typography>
                  <Chip
                    label={selectedCustomer.isBlocked ? 'Blocked' : 'Active'}
                    size="small"
                    sx={{ 
                      bgcolor: selectedCustomer.isBlocked ? '#ffebee' : '#e8f5e9',
                      color: selectedCustomer.isBlocked ? '#f44336' : '#4caf50',
                      fontWeight: 600,
                      mt: 0.5
                    }}
                  />
                </Box>
              </Box>
            </DialogTitle>
            <DialogContent sx={{ pt: 2 }}>
              <List dense>
                <ListItem>
                  <ListItemIcon><PhoneIcon sx={{ color: '#FFB300' }} /></ListItemIcon>
                  <ListItemText primary="Phone" secondary={selectedCustomer.phone} />
                </ListItem>
                <ListItem>
                  <ListItemIcon><EmailIcon sx={{ color: '#FFB300' }} /></ListItemIcon>
                  <ListItemText primary="Email" secondary={selectedCustomer.email || 'Not provided'} />
                </ListItem>
                <ListItem>
                  <ListItemIcon><LocationIcon sx={{ color: '#FFB300' }} /></ListItemIcon>
                  <ListItemText primary="Address" secondary={formatAddress(selectedCustomer.address)} />
                </ListItem>
                <ListItem>
                  <ListItemIcon><CalendarIcon sx={{ color: '#FFB300' }} /></ListItemIcon>
                  <ListItemText 
                    primary="Joined" 
                    secondary={format(new Date(selectedCustomer.createdAt), 'dd MMM yyyy, hh:mm a')} 
                  />
                </ListItem>
                <ListItem>
                  <ListItemIcon><ShippingIcon sx={{ color: '#FFB300' }} /></ListItemIcon>
                  <ListItemText primary="Total Trips" secondary={selectedCustomer.totalTrips} />
                </ListItem>
                <ListItem>
                  <ListItemIcon><MoneyIcon sx={{ color: '#FFB300' }} /></ListItemIcon>
                  <ListItemText primary="Total Spent" secondary={`₹${selectedCustomer.totalSpent?.toLocaleString() || 0}`} />
                </ListItem>
                {selectedCustomer.rating > 0 && (
                  <ListItem>
                    <ListItemIcon><StarIcon sx={{ color: '#FFB300' }} /></ListItemIcon>
                    <ListItemText primary="Rating" secondary={`${selectedCustomer.rating} / 5`} />
                  </ListItem>
                )}
              </List>
            </DialogContent>
            <DialogActions>
              <Button onClick={() => setViewDialogOpen(false)}>Close</Button>
              <Button
                variant="contained"
                onClick={() => {
                  setViewDialogOpen(false);
                  handleEditCustomer(selectedCustomer);
                }}
                sx={{ bgcolor: '#FFB300', '&:hover': { bgcolor: '#FFA000' } }}
              >
                Edit
              </Button>
            </DialogActions>
          </>
        )}
      </Dialog>

      {/* Edit Customer Dialog */}
      <Dialog
        open={editDialogOpen}
        onClose={() => setEditDialogOpen(false)}
        maxWidth="sm"
        fullWidth
        PaperProps={{ sx: { borderRadius: 2 } }}
      >
        <DialogTitle sx={{ bgcolor: '#FFB300', color: '#fff' }}>
          Edit Customer
        </DialogTitle>
        <DialogContent sx={{ pt: 2 }}>
          <TextField
            fullWidth
            label="Name"
            value={editFormData.name}
            onChange={(e) => setEditFormData({ ...editFormData, name: e.target.value })}
            margin="normal"
            required
          />
          <TextField
            fullWidth
            label="Email"
            value={editFormData.email}
            onChange={(e) => setEditFormData({ ...editFormData, email: e.target.value })}
            margin="normal"
            type="email"
          />
          <TextField
            fullWidth
            label="Address (JSON format or plain text)"
            value={editFormData.address}
            onChange={(e) => setEditFormData({ ...editFormData, address: e.target.value })}
            margin="normal"
            multiline
            rows={3}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEditDialogOpen(false)}>Cancel</Button>
          <Button
            variant="contained"
            onClick={handleUpdateCustomer}
            sx={{ bgcolor: '#FFB300', '&:hover': { bgcolor: '#FFA000' } }}
          >
            Save Changes
          </Button>
        </DialogActions>
      </Dialog>

      {/* Confirmation Dialog */}
      <Dialog
        open={confirmDialogOpen}
        onClose={() => setConfirmDialogOpen(false)}
        PaperProps={{ sx: { borderRadius: 2 } }}
      >
        <DialogTitle>Confirm Status Change</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to {customers.find(c => c._id === pendingStatusChange)?.isBlocked ? 'activate' : 'block'} this customer?
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setConfirmDialogOpen(false)}>Cancel</Button>
          <Button
            variant="contained"
            onClick={() => handleToggleStatus(pendingStatusChange)}
            sx={{ bgcolor: '#FFB300', '&:hover': { bgcolor: '#FFA000' } }}
          >
            Confirm
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default UserStatus;