import React, { useEffect, useState } from 'react';
import axios from 'axios';
import LiveOfflineToggle from '../components/LiveOfflineToggle';

function DriverDashboard() {
  const [driver, setDriver] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedImage, setSelectedImage] = useState(null);
  const [driverStatus, setDriverStatus] = useState({ isOnline: false, isAvailable: false });

  useEffect(() => {
    fetchDriverData();
  }, []);

  const fetchDriverData = async () => {
    try {
      const token = localStorage.getItem('driverToken');
      const driverId = localStorage.getItem('driverId');
      
      const response = await axios.get('/api/driver/profile', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setDriver(response.data.data);
      
      const statusResponse = await axios.get(`/api/drivers/${driverId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (statusResponse.data.data) {
        setDriverStatus({
          isOnline: statusResponse.data.data.isOnline || false,
          isAvailable: statusResponse.data.data.isAvailable || false
        });
      }
    } catch (error) {
      console.error('Error fetching driver data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = (newStatus) => {
    setDriverStatus(prev => ({
      ...prev,
      isOnline: newStatus
    }));
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'Verified': return '#28a745';
      case 'Submitted': return '#ffc107';
      case 'Rejected': return '#dc3545';
      default: return '#6c757d';
    }
  };

  const getStatusBgColor = (status) => {
    switch (status) {
      case 'Verified': return '#d4edda';
      case 'Submitted': return '#fff3cd';
      case 'Rejected': return '#f8d7da';
      default: return '#e9ecef';
    }
  };

  const getDocumentIcon = (status) => {
    if (status === 'uploaded' || status === 'verified') {
      return '✓';
    }
    return '○';
  };

  const getDocumentStatusColor = (status) => {
    if (status === 'uploaded' || status === 'verified') return '#28a745';
    return '#dc3545';
  };

  const maskAccountNumber = (accountNumber) => {
    if (!accountNumber) return '';
    const last4 = accountNumber.slice(-4);
    return `****${last4}`;
  };

  const handleLogout = () => {
    localStorage.removeItem('AdminToken');
    window.location.href = '/login';
  };

  if (loading) {
    return <div style={styles.loading}>Loading...</div>;
  }

  if (!driver) {
    return <div style={styles.error}>Unable to load profile</div>;
  }

  const documents = [
    { 
      title: 'Profile Photo', 
      status: driver.documents?.profilePhoto?.status || 'pending',
      image: driver.documents?.profilePhoto?.url
    },
    { 
      title: 'Aadhar Card', 
      status: driver.documents?.aadhar?.status || 'pending',
      image: driver.documents?.aadhar?.url
    },
    { 
      title: 'PAN Card', 
      status: driver.documents?.pan?.status || 'pending',
      image: driver.documents?.pan?.url
    },
    { 
      title: 'Driving License', 
      status: driver.documents?.license?.status || 'pending',
      image: driver.documents?.license?.url,
      details: driver.documents?.license?.number 
        ? `License: ${driver.documents.license.number}` 
        : null,
      extra: driver.documents?.license?.expiry
        ? `Expiry: ${new Date(driver.documents.license.expiry).toLocaleDateString('en-IN')}`
        : null
    },
    { 
      title: 'Vehicle RC', 
      status: driver.documents?.rc?.status || 'pending',
      image: driver.documents?.rc?.url,
      details: driver.documents?.rc?.number 
        ? `RC: ${driver.documents.rc.number}` 
        : null
    },
    { 
      title: 'Vehicle Insurance', 
      status: driver.documents?.insurance?.status || 'pending',
      image: driver.documents?.insurance?.url,
      details: driver.documents?.insurance?.policyNumber
        ? `Policy: ${driver.documents.insurance.policyNumber}`
        : null,
      extra: driver.documents?.insurance?.expiry
        ? `Expiry: ${new Date(driver.documents.insurance.expiry).toLocaleDateString('en-IN')}`
        : null
    },
    { 
      title: 'Vehicle Photo', 
      status: driver.documents?.vehiclePhoto?.status || 'pending',
      image: driver.documents?.vehiclePhoto?.url
    }
  ];

  const getTimelineStep = () => {
    switch (driver.verificationStatus) {
      case 'Verified': return 3;
      case 'Submitted': return 2;
      case 'Pending': return 1;
      default: return 1;
    }
  };

  const currentStep = getTimelineStep();

  return (
    <div style={styles.container}>
      {/* Header Section */}
      <div style={styles.header}>
        <div style={styles.profileSection}>
          <img
            src={driver.photo || '/default-avatar.png'}
            alt={driver.name}
            style={styles.profilePhoto}
          />
          <div style={styles.profileInfo}>
            <h1 style={styles.name}>{driver.name}</h1>
            <span style={{
              ...styles.statusBadge,
              backgroundColor: getStatusBgColor(driver.verificationStatus),
              color: getStatusColor(driver.verificationStatus)
            }}>
              {driver.verificationStatus}
            </span>
          </div>
        </div>
        
        {driver.verificationStatus === 'Rejected' && driver.rejectionReason && (
          <div style={styles.rejectionAlert}>
            <strong>Application Rejected:</strong> {driver.rejectionReason}
          </div>
        )}
      </div>

      {/* Status Timeline */}
      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>Application Status</h2>
        <div style={styles.timeline}>
          <div style={styles.timelineStep}>
            <div style={{
              ...styles.timelineCircle,
              backgroundColor: currentStep >= 1 ? '#FFB300' : '#e0e0e0',
              color: currentStep >= 1 ? '#fff' : '#666'
            }}>
              ✓
            </div>
            <div style={styles.timelineLine}></div>
            <div style={{
              ...styles.timelineLabel,
              color: currentStep >= 1 ? '#FFB300' : '#666'
            }}>
              Application Submitted
            </div>
          </div>
          
          <div style={styles.timelineStep}>
            <div style={{
              ...styles.timelineCircle,
              backgroundColor: currentStep >= 2 ? '#FFB300' : '#e0e0e0',
              color: currentStep >= 2 ? '#fff' : '#666'
            }}>
              {currentStep > 2 ? '✓' : '2'}
            </div>
            <div style={styles.timelineLine}></div>
            <div style={{
              ...styles.timelineLabel,
              color: currentStep >= 2 ? '#FFB300' : '#666'
            }}>
              Documents Under Review
            </div>
          </div>
          
          <div style={styles.timelineStep}>
            <div style={{
              ...styles.timelineCircle,
              backgroundColor: currentStep >= 3 ? '#28a745' : '#e0e0e0',
              color: currentStep >= 3 ? '#fff' : '#666'
            }}>
              {currentStep > 3 ? '✓' : '3'}
            </div>
            <div style={{
              ...styles.timelineLabel,
              color: currentStep >= 3 ? '#28a745' : '#666'
            }}>
              Verification Complete
            </div>
          </div>
        </div>
      </div>

      {/* Documents Section */}
      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>Documents</h2>
        <div style={styles.documentsGrid}>
          {documents.map((doc, index) => (
            <div key={index} style={styles.documentCard}>
              <div style={styles.documentHeader}>
                <h3 style={styles.documentTitle}>{doc.title}</h3>
                <span style={{
                  color: getDocumentStatusColor(doc.status),
                  fontSize: '20px',
                  fontWeight: 'bold'
                }}>
                  {getDocumentIcon(doc.status)}
                </span>
              </div>
              
              {doc.details && (
                <p style={styles.documentDetails}>{doc.details}</p>
              )}
              {doc.extra && (
                <p style={styles.documentExtra}>{doc.extra}</p>
              )}
              
              <div style={styles.documentActions}>
                {doc.image && (
                  <button
                    onClick={() => setSelectedImage(doc.image)}
                    style={styles.viewButton}
                  >
                    View
                  </button>
                )}
                <button style={styles.uploadButton}>
                  {doc.status === 'pending' ? 'Upload' : 'Update'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Vehicle Details Card */}
      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>Vehicle Details</h2>
        <div style={styles.infoCard}>
          <div style={styles.infoRow}>
            <span style={styles.infoLabel}>Vehicle Type</span>
            <span style={styles.infoValue}>{driver.vehicle?.type || 'Not specified'}</span>
          </div>
          <div style={styles.infoRow}>
            <span style={styles.infoLabel}>Vehicle Number</span>
            <span style={styles.infoValue}>{driver.vehicle?.number || 'Not specified'}</span>
          </div>
          <div style={styles.infoRow}>
            <span style={styles.infoLabel}>Model</span>
            <span style={styles.infoValue}>{driver.vehicle?.model || 'Not specified'}</span>
          </div>
          <div style={styles.infoRow}>
            <span style={styles.infoLabel}>Year</span>
            <span style={styles.infoValue}>{driver.vehicle?.year || 'Not specified'}</span>
          </div>
          <div style={styles.infoRow}>
            <span style={styles.infoLabel}>Color</span>
            <span style={styles.infoValue}>{driver.vehicle?.color || 'Not specified'}</span>
          </div>
        </div>
      </div>

      {/* Bank Details Card */}
      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>Bank Details</h2>
        <div style={styles.infoCard}>
          <div style={styles.infoRow}>
            <span style={styles.infoLabel}>Account Holder</span>
            <span style={styles.infoValue}>{driver.bankDetails?.accountHolder || 'Not specified'}</span>
          </div>
          <div style={styles.infoRow}>
            <span style={styles.infoLabel}>Account Number</span>
            <span style={styles.infoValue}>
              {driver.bankDetails?.accountNumber 
                ? maskAccountNumber(driver.bankDetails.accountNumber) 
                : 'Not specified'}
            </span>
          </div>
          <div style={styles.infoRow}>
            <span style={styles.infoLabel}>Bank Name</span>
            <span style={styles.infoValue}>{driver.bankDetails?.bankName || 'Not specified'}</span>
          </div>
          <div style={styles.infoRow}>
            <span style={styles.infoLabel}>IFSC Code</span>
            <span style={styles.infoValue}>{driver.bankDetails?.ifsc || 'Not specified'}</span>
          </div>
        </div>
      </div>

      {/* Verified Status Content */}
      {driver.verificationStatus === 'Verified' && (
        <div style={styles.section}>
          {/* Live/Offline Toggle */}
          <div style={{ marginBottom: '20px' }}>
            <LiveOfflineToggle 
              driverId={driver._id || localStorage.getItem('driverId')}
              initialStatus={driverStatus.isOnline}
              onStatusChange={handleStatusChange}
            />
          </div>
          
          <div style={styles.earningsCard}>
            <h3 style={styles.earningsTitle}>Earnings Preview</h3>
            <div style={styles.earningsAmount}>
              ₹{driver.earnings?.today || 0}
            </div>
            <p style={styles.earningsLabel}>Today's Earnings</p>
            <div style={styles.earningsStats}>
              <div style={styles.stat}>
                <span style={styles.statValue}>{driver.earnings?.trips || 0}</span>
                <span style={styles.statLabel}>Trips</span>
              </div>
              <div style={styles.stat}>
                <span style={styles.statValue}>₹{driver.earnings?.week || 0}</span>
                <span style={styles.statLabel}>This Week</span>
              </div>
            </div>
          </div>
          
          <button style={styles.startDrivingButton}>
            Start Driving
          </button>
        </div>
      )}

      {/* Action Buttons */}
      <div style={styles.actionsSection}>
        <button style={styles.updateButton}>
          Update Documents
        </button>
        <button style={styles.supportButton}>
          Contact Support
        </button>
        <button onClick={handleLogout} style={styles.logoutButton}>
          Logout
        </button>
      </div>

      {/* Image Modal */}
      {selectedImage && (
        <div style={styles.modal} onClick={() => setSelectedImage(null)}>
          <div style={styles.modalContent} onClick={(e) => e.stopPropagation()}>
            <img src={selectedImage} alt="Document" style={styles.modalImage} />
            <button 
              onClick={() => setSelectedImage(null)}
              style={styles.closeButton}
            >
              ✕ Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

