// pages/WebhookTester.jsx
import React, { useState } from 'react';
import './WebhookTester.css';

const API_BASE_URL = 'https://porterbackend-iyxh.onrender.com/api';

const WebhookTester = () => {
  const [webhookResponse, setWebhookResponse] = useState(null);
  const [loading, setLoading] = useState(false);
  const [webhookData, setWebhookData] = useState({
    orderId: 'order_test_123456789',
    paymentId: 'pay_test_123456789',
    amount: 50000,
    event: 'payment.captured'
  });
  const [webhookSecret, setWebhookSecret] = useState('');

  const generateSignature = async (payload) => {
    return 'test_signature_' + Buffer.from(JSON.stringify(payload)).toString('base64').substring(0, 20);
  };

  const sendWebhook = async () => {
    setLoading(true);
    
    const payload = {
      entity: "event",
      event: webhookData.event,
      payload: {
        payment: {
          entity: {
            id: webhookData.paymentId,
            amount: webhookData.amount,
            currency: "INR",
            status: webhookData.event === 'payment.captured' ? 'captured' : 'failed',
            order_id: webhookData.orderId,
            method: "card",
            email: "customer@example.com",
            contact: "+919876543210",
            notes: {
              rideId: "RID12345678"
            }
          }
        }
      },
      created_at: Math.floor(Date.now() / 1000)
    };

    const signature = await generateSignature(payload);

    try {
      const response = await fetch(`${API_BASE_URL}/payments/webhook/razorpay`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-razorpay-signature': signature
        },
        body: JSON.stringify(payload)
      });

      const data = await response.json();
      console.log('Webhook Response:', data);
      setWebhookResponse({
        status: response.status,
        data: data
      });

    } catch (error) {
      console.error('Webhook error:', error);
      setWebhookResponse({
        status: 500,
        error: error.message
      });
    } finally {
      setLoading(false);
    }
  };

  const webhookPresets = {
    captured: {
      event: 'payment.captured',
      amount: 50000,
      paymentId: 'pay_captured_' + Date.now()
    },
    failed: {
      event: 'payment.failed',
      amount: 50000,
      paymentId: 'pay_failed_' + Date.now()
    },
    refunded: {
      event: 'refund.processed',
      amount: 50000,
      paymentId: 'pay_refunded_' + Date.now()
    }
  };

  return (
    <div className="wt-container">
      <h1 className="wt-title">🔔 Razorpay Webhook Tester</h1>

      <div className="wt-config-card">
        <h2 className="wt-section-title">Webhook Configuration</h2>
        
        <div className="wt-url-display">
          <strong>Webhook URL:</strong>
          <code className="wt-url-code">{API_BASE_URL}/payments/webhook/razorpay</code>
        </div>

        <div className="wt-input-group">
          <label className="wt-label">Webhook Secret (for signature):</label>
          <input
            className="wt-input"
            type="password"
            value={webhookSecret}
            onChange={(e) => setWebhookSecret(e.target.value)}
            placeholder="Enter your webhook secret"
          />
        </div>
      </div>

      <div className="wt-form-card">
        <h2 className="wt-section-title">📦 Webhook Payload</h2>

        <div className="wt-preset-buttons">
          <button onClick={() => setWebhookData(webhookPresets.captured)} className="wt-btn wt-btn-success">
            ✅ Payment Captured
          </button>
          <button onClick={() => setWebhookData(webhookPresets.failed)} className="wt-btn wt-btn-danger">
            ❌ Payment Failed
          </button>
          <button onClick={() => setWebhookData(webhookPresets.refunded)} className="wt-btn wt-btn-warning">
            ↩️ Refund Processed
          </button>
        </div>

        <div className="wt-input-group">
          <label className="wt-label">Event Type:</label>
          <select 
            className="wt-select"
            value={webhookData.event}
            onChange={(e) => setWebhookData({...webhookData, event: e.target.value})}
          >
            <option value="payment.captured">payment.captured</option>
            <option value="payment.failed">payment.failed</option>
            <option value="order.paid">order.paid</option>
            <option value="refund.processed">refund.processed</option>
          </select>
        </div>

        <div className="wt-input-group">
          <label className="wt-label">Order ID:</label>
          <input
            className="wt-input"
            type="text"
            value={webhookData.orderId}
            onChange={(e) => setWebhookData({...webhookData, orderId: e.target.value})}
            placeholder="order_test_123456789"
          />
        </div>

        <div className="wt-input-group">
          <label className="wt-label">Payment ID:</label>
          <input
            className="wt-input"
            type="text"
            value={webhookData.paymentId}
            onChange={(e) => setWebhookData({...webhookData, paymentId: e.target.value})}
            placeholder="pay_test_123456789"
          />
        </div>

        <div className="wt-input-group">
          <label className="wt-label">Amount (in paise):</label>
          <input
            className="wt-input"
            type="number"
            value={webhookData.amount}
            onChange={(e) => setWebhookData({...webhookData, amount: parseInt(e.target.value)})}
          />
          <small className="wt-hint">₹{webhookData.amount / 100}</small>
        </div>

        <button 
          className="wt-btn wt-btn-primary wt-btn-large"
          onClick={sendWebhook} 
          disabled={loading}
        >
          {loading ? 'Sending...' : '🚀 Send Test Webhook'}
        </button>
      </div>

      {webhookResponse && (
        <div className="wt-response-card">
          <h3 className="wt-response-title">📨 Webhook Response</h3>
          <div className={`wt-status-badge ${webhookResponse.status === 200 ? 'wt-status-success' : 'wt-status-error'}`}>
            Status: {webhookResponse.status}
          </div>
          <pre className="wt-response-data">
            {JSON.stringify(webhookResponse.data || webhookResponse.error, null, 2)}
          </pre>
        </div>
      )}

      <div className="wt-info-card">
        <h3 className="wt-info-title">ℹ️ Webhook Testing Tips</h3>
        <ul className="wt-info-list">
          <li>Webhook signature must match for successful verification</li>
          <li>For testing, you can temporarily disable signature verification</li>
          <li>Check your server logs for webhook processing details</li>
          <li>Webhook should return 200 OK for successful processing</li>
        </ul>
      </div>
    </div>
  );
};

export default WebhookTester;