// pages/LiveUPIPayment.jsx
import React, { useState } from 'react';
import './LiveUPIPayment.css';

const API_BASE_URL = 'https://godelivo.com/api';

const LiveUPIPayment = () => {
  const [authToken, setAuthToken] = useState('');
  const [rideId, setRideId] = useState('RID02360983578');
  const [loading, setLoading] = useState(false);
  const [paymentStatus, setPaymentStatus] = useState(null);
  const [orderDetails, setOrderDetails] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState('upi');

  // Your live Razorpay key (hardcoded as fallback)
  const RAZORPAY_KEY_ID = 'rzp_live_ST0TZQUt1IwsqU';

  const initiatePayment = async () => {
    if (!authToken || !rideId) {
      alert('Please enter Auth Token and Ride ID');
      return;
    }

    setLoading(true);
    setPaymentStatus(null);
    
    try {
      // 1. Create order on your backend
      console.log('📝 Creating payment order...');
      const orderResponse = await fetch(`${API_BASE_URL}/payments/create-order`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${authToken}`
        },
        body: JSON.stringify({ rideId })
      });

      const orderData = await orderResponse.json();
      console.log('Order Response:', orderData);

      if (!orderData.success) {
        throw new Error(orderData.message || 'Failed to create order');
      }

      const { orderId, amount, customerName, customerPhone } = orderData.data;
      setOrderDetails(orderData.data);

      // 2. Load Razorpay script if not already loaded
      await loadRazorpayScript();

      // 3. Configure Razorpay options
      const options = {
        key: RAZORPAY_KEY_ID, // Use hardcoded key directly
        amount: amount,
        currency: 'INR',
        name: 'Porter Delivery',
        description: `Ride Payment - ${rideId}`,
        order_id: orderId,
        handler: async function(response) {
          console.log('✅ Payment Success:', response);
          await verifyPayment(response);
        },
        prefill: {
          name: customerName || 'Test User',
          contact: customerPhone || '9999999999',
          email: 'customer@example.com'
        },
        notes: {
          rideId: rideId
        },
        theme: {
          color: '#667eea'
        },
        modal: {
          ondismiss: function() {
            console.log('Payment modal closed');
            setLoading(false);
          }
        },
        // Enable all payment methods
        method: {
          upi: true,
          card: true,
          netbanking: true,
          wallet: true
        }
      };

      console.log('🚀 Opening Razorpay with options:', options);

      // 4. Open Razorpay checkout
      const razorpay = new window.Razorpay(options);
      
      razorpay.on('payment.failed', function(response) {
        console.error('❌ Payment Failed:', response.error);
        setPaymentStatus({
          success: false,
          message: `Payment failed: ${response.error.description}`,
          details: response.error
        });
        setLoading(false);
      });

      razorpay.open();

    } catch (error) {
      console.error('❌ Payment initiation error:', error);
      setPaymentStatus({
        success: false,
        message: error.message
      });
      setLoading(false);
    }
  };

  // Function to load Razorpay script
  const loadRazorpayScript = () => {
    return new Promise((resolve, reject) => {
      // Check if script is already loaded
      if (window.Razorpay) {
        resolve();
        return;
      }

      const script = document.createElement('script');
      script.src = 'https://checkout.razorpay.com/v1/checkout.js';
      script.async = true;
      
      script.onload = () => {
        console.log('✅ Razorpay script loaded');
        resolve();
      };
      
      script.onerror = () => {
        reject(new Error('Failed to load Razorpay script'));
      };

      document.body.appendChild(script);
    });
  };

  const verifyPayment = async (response) => {
    try {
      const verifyResponse = await fetch(`${API_BASE_URL}/payments/verify`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${authToken}`
        },
        body: JSON.stringify({
          rideId: rideId,
          razorpay_payment_id: response.razorpay_payment_id,
          razorpay_order_id: response.razorpay_order_id,
          razorpay_signature: response.razorpay_signature
        })
      });

      const verifyData = await verifyResponse.json();
      console.log('Verify Response:', verifyData);

      if (verifyData.success) {
        setPaymentStatus({
          success: true,
          message: '✅ Payment successful and verified!',
          data: verifyData.data
        });

        // Check final status
        checkPaymentStatus();
      } else {
        setPaymentStatus({
          success: false,
          message: '❌ Payment verification failed: ' + verifyData.message
        });
      }
    } catch (error) {
      console.error('Verification error:', error);
      setPaymentStatus({
        success: false,
        message: '❌ Verification error: ' + error.message
      });
    } finally {
      setLoading(false);
    }
  };

  const checkPaymentStatus = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/payments/${rideId}/status`, {
        headers: {
          'Authorization': `Bearer ${authToken}`
        }
      });

      const data = await response.json();
      console.log('Payment Status:', data);
      
      if (data.success) {
        setPaymentStatus(prev => ({
          ...prev,
          statusCheck: data.data
        }));
      }
    } catch (error) {
      console.error('Status check error:', error);
    }
  };

  const handleUPIPayment = (app) => {
    console.log(`Selected UPI app: ${app}`);
    initiatePayment();
  };

  return (
    <div className="live-payment-container">
      <h1 className="live-title">💰 Live UPI Payment Test</h1>
      
      <div className="live-warning">
        <strong>⚠️ LIVE TRANSACTION</strong>
        <p>You are about to make a real payment of ₹175. This will charge your UPI account.</p>
      </div>

      <div className="live-credentials">
        <h3>🔐 Authentication</h3>
        <div className="input-group">
          <label>Auth Token (JWT):</label>
          <textarea
            className="live-input"
            value={authToken}
            onChange={(e) => setAuthToken(e.target.value)}
            placeholder="Enter your JWT token"
            rows="3"
          />
        </div>

        <div className="input-group">
          <label>Ride ID:</label>
          <input
            className="live-input"
            type="text"
            value={rideId}
            onChange={(e) => setRideId(e.target.value)}
            readOnly
          />
        </div>
      </div>

      <div className="live-order-details">
        <h3>📦 Order Details</h3>
        <div className="details-grid">
          <div className="detail-item">
            <span className="label">Order ID:</span>
            <span className="value">{orderDetails?.orderId || 'order_ST1VTP3zhprrC0'}</span>
          </div>
          <div className="detail-item">
            <span className="label">Amount:</span>
            <span className="value highlight">₹175.00</span>
          </div>
          <div className="detail-item">
            <span className="label">Ride ID:</span>
            <span className="value">RID02360983578</span>
          </div>
          <div className="detail-item">
            <span className="label">Key ID:</span>
            <span className="value">{RAZORPAY_KEY_ID}</span>
          </div>
        </div>
      </div>

      <div className="payment-methods">
        <h3>💳 Select Payment Method</h3>
        <div className="method-buttons">
          <button 
            className={`method-btn ${paymentMethod === 'upi' ? 'active' : ''}`}
            onClick={() => setPaymentMethod('upi')}
          >
            <span className="method-icon">📱</span>
            <span className="method-name">UPI</span>
            <span className="method-desc">Google Pay, PhonePe, Paytm</span>
          </button>
          <button 
            className={`method-btn ${paymentMethod === 'card' ? 'active' : ''}`}
            onClick={() => setPaymentMethod('card')}
          >
            <span className="method-icon">💳</span>
            <span className="method-name">Card</span>
            <span className="method-desc">Credit/Debit Card</span>
          </button>
        </div>
      </div>

      {paymentMethod === 'upi' && (
        <div className="upi-section">
          <h3>📱 UPI Payment Options</h3>
          
          <div className="upi-apps">
            <button 
              className="upi-app-btn" 
              onClick={() => handleUPIPayment('gpay')} 
              disabled={loading}
            >
              <span className="app-icon">📱</span>
              <span className="app-name">Google Pay</span>
              <span className="app-id">@okhdfcbank</span>
            </button>
            <button 
              className="upi-app-btn" 
              onClick={() => handleUPIPayment('phonepe')} 
              disabled={loading}
            >
              <span className="app-icon">📱</span>
              <span className="app-name">PhonePe</span>
              <span className="app-id">@ybl</span>
            </button>
            <button 
              className="upi-app-btn" 
              onClick={() => handleUPIPayment('paytm')} 
              disabled={loading}
            >
              <span className="app-icon">📱</span>
              <span className="app-name">Paytm</span>
              <span className="app-id">@paytm</span>
            </button>
            <button 
              className="upi-app-btn" 
              onClick={() => handleUPIPayment('other')} 
              disabled={loading}
            >
              <span className="app-icon">📱</span>
              <span className="app-name">Other UPI</span>
              <span className="app-id">Enter manually</span>
            </button>
          </div>

          <div className="upi-manual">
            <p>Or enter UPI ID manually in Razorpay checkout:</p>
            <div className="upi-id-box">
              <code>your-vpa@okhdfcbank</code>
            </div>
          </div>
        </div>
      )}

      {paymentMethod === 'card' && (
        <div className="card-section">
          <h3>💳 Card Payment</h3>
          <button 
            className="pay-now-btn"
            onClick={initiatePayment}
            disabled={loading}
          >
            {loading ? 'Processing...' : 'Pay with Card'}
          </button>
          <div className="test-cards">
            <p>Test Cards (for sandbox only):</p>
            <ul>
              <li>Success: 4111 1111 1111 1111</li>
              <li>Fail: 4242 4242 4242 4242</li>
              <li>Expiry: Any future date</li>
              <li>CVV: Any 3 digits</li>
            </ul>
          </div>
        </div>
      )}

      <button 
        className="initiate-payment-btn"
        onClick={initiatePayment}
        disabled={loading || !authToken}
      >
        {loading ? '⏳ Processing...' : '🚀 Pay Now ₹175'}
      </button>

      {paymentStatus && (
        <div className={`payment-status ${paymentStatus.success ? 'success' : 'error'}`}>
          <h3>{paymentStatus.success ? '✅ Payment Successful' : '❌ Payment Failed'}</h3>
          <p>{paymentStatus.message}</p>
          
          {paymentStatus.data && (
            <div className="status-details">
              <pre>{JSON.stringify(paymentStatus.data, null, 2)}</pre>
            </div>
          )}

          {paymentStatus.statusCheck && (
            <div className="status-check">
              <h4>Final Status:</h4>
              <p>Payment Status: {paymentStatus.statusCheck.paymentStatus}</p>
              <p>Order ID: {paymentStatus.statusCheck.orderId}</p>
              {paymentStatus.statusCheck.paymentDetails && (
                <p>Transaction ID: {paymentStatus.statusCheck.paymentDetails.paymentId}</p>
              )}
            </div>
          )}
        </div>
      )}

      <div className="live-instructions">
        <h4>📋 Instructions for Live UPI Payment:</h4>
        <ol>
          <li>Enter your valid JWT token</li>
          <li>Click "Pay Now ₹175"</li>
          <li>Razorpay checkout will open</li>
          <li>Select UPI as payment method</li>
          <li>Enter your UPI ID (e.g., yourname@okhdfcbank)</li>
          <li>Approve payment in your UPI app</li>
          <li>Payment will be verified automatically</li>
        </ol>

        <div className="live-warning-small">
          <p>⚠️ This is a REAL transaction. Your account will be charged ₹175.</p>
          <p>✅ Test UPI IDs: yourname@okhdfcbank, yourname@ybl, yourname@paytm</p>
          <p>💡 Make sure you have sufficient balance in your UPI account</p>
        </div>
      </div>
    </div>
  );
};

export default LiveUPIPayment;