const API_URL = process.env.REACT_APP_API_URL || 'https://godelivo.com';

const getDriverToken = () => localStorage.getItem('driverToken');

const getDriverHeaders = () => ({
  'Content-Type': 'application/json',
  'Authorization': `Bearer ${getDriverToken()}`
});

const handleResponse = async (response) => {
  const data = await response.json();
  if (!response.ok) {
    if (response.status === 401) {
      localStorage.removeItem('driverToken');
      localStorage.removeItem('driverId');
      window.location.href = '/driver-login';
    }
    throw new Error(data.message || 'Something went wrong');
  }
  return data;
};

const driverApi = {
  toggleOnlineStatus: (isOnline) =>
    fetch(`${API_URL}/api/driver/toggle-online`, {
      method: 'POST',
      headers: getDriverHeaders(),
      body: JSON.stringify({ isOnline }),
    }).then(handleResponse),

  getDriverProfile: () =>
    fetch(`${API_URL}/api/driver/profile`, {
      headers: getDriverHeaders(),
    }).then(handleResponse),

  updateLocation: (driverId, latitude, longitude) =>
    fetch(`${API_URL}/api/drivers/${driverId}/location`, {
      method: 'PATCH',
      headers: getDriverHeaders(),
      body: JSON.stringify({ latitude, longitude }),
    }).then(handleResponse),

  updateAvailability: (driverId, isAvailable) =>
    fetch(`${API_URL}/api/drivers/${driverId}/availability`, {
      method: 'PATCH',
      headers: getDriverHeaders(),
      body: JSON.stringify({ isAvailable }),
    }).then(handleResponse),
};

export default driverApi;
